async function boot(){applyTheme();try{state.me=await api('/api/auth/me')}catch{}const adminPortal=isAdminPortal();const reviewMatch=location.pathname.match(/^\/exam-review\/(\d+)\/?$/);const certReviewMatch=location.pathname.match(/^\/certificate-exam\/([^/]+)\/?$/);if(reviewMatch){state.reviewResultId=Number(reviewMatch[1]);state.view=state.me?.user?'exam-review':'login'}else if(certReviewMatch){state.certificateReviewNumber=decodeURIComponent(certReviewMatch[1]);state.view='certificate-exam'}else if(adminPortal)state.view=state.me?.admin?'admin':'admin-login';else if(state.me?.user&&(location.pathname==='/results'||location.pathname==='/assessments'))state.view='results';else if(state.me?.user&&location.pathname==='/certificates')state.view='certificates';else if(state.me?.user&&location.pathname==='/courses')state.view='courses';else if(state.me?.user&&location.pathname==='/challenges')state.view='challenges';else if(state.me?.user&&location.pathname==='/tasks')state.view='tasks';else if(state.me?.user&&location.pathname==='/assessments')state.view='results';else state.view=state.me?.user?'dashboard':'home';render()}
function render(){const adminPortal=isAdminPortal();if(adminPortal){if(state.view==='admin'&&state.me?.admin)return renderAdmin();return renderAdminLogin()}if(state.view==='admin-login'||state.view==='admin')state.view='home';if(state.view==='login')return renderLogin();if(state.view==='register')return renderRegister();if(state.view==='dashboard'&&state.me?.user)return renderDashboard();if((state.view==='courses'||state.view==='challenges')&&state.me?.user)return renderStudentLearning(state.view);if(state.view==='tasks'&&state.me?.user)return renderStudentTasks();if(state.view==='course-player'&&state.me?.user)return renderCoursePlayer(state.coursePlayerCourseId,state.coursePlayerLessonId);if(state.view==='results'&&state.me?.user)return renderStudentResults();if(state.view==='certificates'&&state.me?.user)return renderStudentCertificates();if(state.view==='exam'&&state.me?.user)return renderExam();if(state.view==='exam-review'&&state.me?.user)return renderStandaloneExamReview(state.reviewResultId);if(state.view==='certificate-exam')return renderPublicCertificateExam(state.certificateReviewNumber);if(state.view==='result')return renderResult(state.lastResult);state.view='home';renderHome()}
async function verifyCertificate(e){
  e.preventDefault();
  const form=e.target;
  const id=String(new FormData(form).get('certificateId')||'').trim().toUpperCase();
  if(!id){state.verifyResult={error:'Please enter a certificate ID.'};renderHome();return;}
  state.verifyLoading=true;state.verifyResult=null;renderHome();
  try{state.verifyResult=await api(`/api/public/certificate-verify?id=${encodeURIComponent(id)}`)}
  catch(x){state.verifyResult={error:x.message||'Certificate ID not found'}}
  finally{state.verifyLoading=false;renderHome();}
}
