function renderResult(r){
  // Defensive fallbacks for older result payloads / cached Worker responses.
  const fallbackQuestionCount=Number(r.questionCount)>0?Number(r.questionCount):(Array.isArray(state.questions)?state.questions.length:0);
  const fallbackAnsweredCount=Number(r.answeredCount)>=0?Number(r.answeredCount):(Array.isArray(state.questions)?state.questions.filter(q=>state.answers?.[q.id]).length:0);
  const fallbackPassingPercentage=Number.isFinite(Number(r.passingPercentage))?Number(r.passingPercentage):50;
  const pct=Math.max(0,Math.min(100,Number(r.percentage)||0));
  const ar=state.lang==='ar';
  const passed=!!r.passed;
  const statusText=passed?(ar?'ناجح':'Passed'):(ar?'لم ينجح':'Not passed');
  const message=passed?(ar?'لقد اجتزت هذا الامتحان بنجاح.':'You passed this assessment.'):(ar?'لم تصل إلى درجة النجاح هذه المرة. استمر في التدريب وحاول مرة أخرى.':'You did not reach the passing mark this time. Keep practicing and try again.');
  app.innerHTML=layout(`<main class="page result-page"><div class="result-shell">
    <div class="result-header"><div><div class="eyebrow">${ar?'اكتمل الامتحان':'Assessment complete'}</div><h1>${esc(r.examTitle)}</h1><p class="muted">${ar?'النتيجة النهائية':'Overall score'} · ${fmtDate(r.submittedAt||new Date().toISOString())}</p></div><span class="result-status ${passed?'is-pass':'is-fail'}"><span class="status-dot"></span>${statusText}</span></div>
    <section class="result-hero card">
      <div class="score-ring" style="--score:${pct}%"><div class="score-ring-inner"><strong>${pct.toFixed(1)}%</strong><span>${ar?'النتيجة':'Score'}</span></div></div>
      <div class="result-summary"><div class="eyebrow">${ar?'أداءك':'Your performance'}</div><h2>${message}</h2><p class="muted">${ar?'هذه النتيجة محسوبة تلقائياً بناءً على إجاباتك ودرجة النجاح المحددة للامتحان.':'This result was calculated automatically from your answers and the exam passing requirement.'}</p></div>
    </section>
    ${passed&&r.certificate?.verificationUrl?`<section class="card" style="margin-top:18px;padding:22px;border:1px solid #d9e8df;background:#f7fcf9"><div class="eyebrow">Credential issued</div><h3 style="margin:6px 0">Your certificate is ready</h3><p class="muted" style="margin:0 0 14px">Certificate ID: <b>${esc(r.certificate.certificateNumber||'')}</b></p><div class="actions"><a class="btn orange" href="${esc(r.certificate.verificationUrl)}" target="_blank" rel="noopener">Open Certificate ↗</a><button class="btn ghost" onclick="copyStudentId('${esc(r.certificate.verificationUrl).replaceAll("'","&#39;")}')">Copy Verification Link</button></div></section>`:''}
    <section class="result-metrics">
      <div class="result-metric card"><span>${ar?'النقاط المحصلة':'Points earned'}</span><strong>${r.score} <small>/ ${r.totalPoints}</small></strong></div>
      <div class="result-metric card"><span>${ar?'درجة النجاح':'Pass mark'}</span><strong>${fallbackPassingPercentage.toFixed(0)}%</strong></div>
      <div class="result-metric card"><span>${ar?'الأسئلة المُجاب عنها':'Questions answered'}</span><strong>${fallbackAnsweredCount} <small>/ ${fallbackQuestionCount}</small></strong></div>
    </section>
    <div class="result-actions">${passed&&r.certificate?.verificationUrl?`<a class="btn orange" href="${esc(r.certificate.verificationUrl)}" target="_blank" rel="noopener">${ar?'فتح الشهادة':'Open Certificate'} ↗</a>`:''}${passed&&r.certificate?.verificationUrl?`<button class="btn ghost" onclick="copyStudentId('${esc(r.certificate.verificationUrl).replaceAll("'","&#39;")}')">${ar?'نسخ رابط الشهادة':'Copy Certificate Link'}</button>`:''}${!passed&&r.examId?`<button class="btn orange" onclick="startExam(${Number(r.examId)})">${ar?'إعادة الامتحان':'Retake Exam'} ↗</button>`:''}<button class="btn ghost" onclick="go('dashboard')">${ar?'العودة إلى لوحة التحكم':'Back to Dashboard'} ↗</button></div>
  </div></main>`);
  if(state.lang==='ar')translateUI();
}
async function renderAdmin(){app.innerHTML=layout(`<div class="admin-layout"><aside class="sidebar"><button class="side-btn ${state.adminTab==='overview'?'active':''}" onclick="adminTab('overview')">Overview</button><button class="side-btn ${state.adminTab==='students'?'active':''}" onclick="adminTab('students')">Students</button><button class="side-btn ${state.adminTab==='courses'?'active':''}" onclick="adminTab('courses')">Courses</button><button class="side-btn ${state.adminTab==='challenges'?'active':''}" onclick="adminTab('challenges')">Challenges</button><button class="side-btn ${state.adminTab==='cases'?'active':''}" onclick="adminTab('cases')">Case Studies</button><button class="side-btn ${state.adminTab==='case-submissions'?'active':''}" onclick="adminTab('case-submissions')">Case Submissions</button><button class="side-btn ${state.adminTab==='enrollments'?'active':''}" onclick="adminTab('enrollments')">Enrollments</button><button class="side-btn ${state.adminTab==='tasks'?'active':''}" onclick="adminTab('tasks')">Tasks</button><button class="side-btn ${state.adminTab==='exams'?'active':''}" onclick="adminTab('exams')">Exams</button><button class="side-btn ${state.adminTab==='results'?'active':''}" onclick="adminTab('results')">Results</button><button class="side-btn ${state.adminTab==='certificates'?'active':''}" onclick="adminTab('certificates')">Certificates & Email</button>${state.me.admin.role==='super_admin'?`<button class="side-btn ${state.adminTab==='admins'?'active':''}" onclick="adminTab('admins')">Admin Users</button>`:''}</aside><main class="admin-main" id="admin-main"></main></div>`);await loadAdminTab()}
function adminTab(t){state.adminTab=t;renderAdmin()}
async function loadAdminTab(){const el=document.getElementById('admin-main');if(state.adminTab==='overview')return adminOverview(el);if(state.adminTab==='students')return adminStudents(el);if(state.adminTab==='courses')return adminLearningCourses(el);if(state.adminTab==='challenges')return adminLearningChallenges(el);if(state.adminTab==='cases')return adminLearningCases(el);if(state.adminTab==='case-submissions')return adminCaseSubmissions(el);if(state.adminTab==='enrollments')return adminLearningEnrollments(el);if(state.adminTab==='tasks')return adminLearningTasks(el);if(state.adminTab==='exams')return adminExams(el);if(state.adminTab==='results')return adminResults(el);if(state.adminTab==='certificates')return adminCertificates(el);if(state.adminTab==='admins')return adminAdmins(el)}
async function adminOverview(el){try{const d=await api('/api/admin/stats');let certRows=[];try{certRows=await api('/api/admin/certificates')}catch(certErr){console.warn('Certificate dashboard data unavailable:',certErr)}const certSent=certRows.filter(c=>c.email_status==='sent').length;const certPending=certRows.filter(c=>['not_sent','failed'].includes(c.email_status||'not_sent')).length;const certFailed=certRows.filter(c=>c.email_status==='failed').length;el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Control center</div><h1>Overview</h1><p class="muted">A live snapshot of your assessment platform.</p></div></div><div class="kpis admin-kpis"><div class="card kpi"><div class="kpi-label">Students</div><div class="num">${d.students}</div><small>Registered accounts</small></div><div class="card kpi"><div class="kpi-label">Active exams</div><div class="num">${d.activeExams}</div><small>${d.exams} total exams</small></div><div class="card kpi"><div class="kpi-label">Completed</div><div class="num">${d.completedAttempts}</div><small>${d.attempts} total attempts</small></div><div class="card kpi"><div class="kpi-label">Average score</div><div class="num">${d.averagePercentage.toFixed(1)}%</div><small>Across results</small></div><div class="card kpi"><div class="kpi-label">Pass rate</div><div class="num success-text">${d.passRate.toFixed(1)}%</div><small>${d.passedResults} passed</small></div><div class="card kpi"><div class="kpi-label">Question bank</div><div class="num">${d.questions}</div><small>Questions available</small></div></div><section class="card" style="margin-top:14px"><div style="display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap"><div><div class="eyebrow">Certificate email delivery</div><h3 style="margin:5px 0 6px">Send and manage certificate emails</h3><p class="muted" style="margin:0">Automatic emails for new certificates and a bulk sender for older certificates.</p></div><div class="actions"><button class="btn orange" onclick="adminTab('certificates')">Open Certificate Email Center →</button>${certPending?`<button class="btn ghost" onclick="sendPendingCertificateEmails()">Send pending (${certPending})</button>`:''}</div></div><div class="grid grid-3" style="margin-top:14px"><div><span class="small-text muted">Certificates</span><b style="display:block;font-size:22px">${certRows.length}</b></div><div><span class="small-text muted">Emails sent</span><b style="display:block;font-size:22px">${certSent}</b></div><div><span class="small-text muted">Need attention</span><b style="display:block;font-size:22px">${certPending}</b>${certFailed?`<span class="small-text danger-text">${certFailed} failed</span>`:''}</div></div></section><div class="grid grid-2 admin-section"><div class="card insight-card"><div class="eyebrow">Performance</div><h3>Assessment health</h3><div class="metric-list"><div><span>Passed</span><b>${d.passedResults}</b></div><div><span>Not passed</span><b>${d.failedResults}</b></div><div><span>Scheduled exams</span><b>${d.scheduledExams}</b></div></div></div><div class="card insight-card"><div class="eyebrow">Admin</div><h3>Control center</h3><p class="muted">Signed in as <b>${esc(state.me.admin.username)}</b> · ${esc(state.me.admin.role)}</p><div class="actions"><button class="btn ghost" onclick="adminTab('exams')">Manage exams →</button><button class="btn orange" onclick="adminTab('results')">View results →</button></div></div></div>`}catch(x){showError(x.message||'Could not load dashboard statistics','Dashboard statistics unavailable')}}
async function adminStudents(el){const rows=await api('/api/admin/students');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">People</div><h1>Students</h1></div><div class="toolbar"><input id="studentSearch" placeholder="Search students…" oninput="searchStudents()"></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Student ID</th><th>Name</th><th>Email</th><th>Phone</th><th>Status</th><th>Joined</th><th></th></tr></thead><tbody id="students-body">${studentRows(rows)}</tbody></table></div></div>`}
function studentRows(rows){return rows.map(r=>`<tr><td><button type="button" class="copy-id" title="Copy student ID" onclick="copyStudentId('${esc(r.student_id).replaceAll("'","&#39;")}')"><b>${esc(r.student_id)}</b><span>⧉</span></button></td><td><b>${esc(r.full_name)}</b></td><td>${esc(r.email)}</td><td>${r.phone?`<a class="phone-link" href="tel:${esc(r.phone)}">${esc(r.phone)}</a>`:`<span class="muted">—</span>`}</td><td><span class="pill">${r.status}</span></td><td>${fmtDate(r.created_at)}</td><td><button class="btn small ghost" onclick="studentDetail(${r.id})">Manage</button></td></tr>`).join('')||`<tr><td colspan="7" class="empty">No students found.</td></tr>`}
async function copyStudentId(id){try{await navigator.clipboard.writeText(id);showToast(`Copied ${id}`)}catch{const t=document.createElement('textarea');t.value=id;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove();showToast(`Copied ${id}`)}}
let searchTimer;async function searchStudents(){clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{const q=document.getElementById('studentSearch').value;const rows=await api('/api/admin/students?q='+encodeURIComponent(q));document.getElementById('students-body').innerHTML=studentRows(rows)},250)}
async function studentDetail(id){const d=await api(`/api/admin/students/${id}`);openModal(`<div class="modal-head"><div><div class="eyebrow">Student account</div><h2>${esc(d.student.full_name)}</h2><p class="muted">Manage access, credentials and exam history.</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="grid grid-2"><div class="card student-account-card"><div class="account-id-label">Student ID</div><button type="button" class="account-id" onclick="copyStudentId('${esc(d.student.student_id).replaceAll("'","&#39;")}')"><strong>${esc(d.student.student_id)}</strong><span>Copy</span></button><p>${esc(d.student.email)}</p><p><b>Phone:</b> ${d.student.phone?`<a class="phone-link" href="tel:${esc(d.student.phone)}">${esc(d.student.phone)}</a>`:`<span class="muted">Not provided</span>`}</p><span class="pill">${d.student.status}</span><div class="actions" style="margin-top:15px"><button class="btn small ${d.student.status==='active'?'danger':'orange'}" onclick="toggleStudent(${id},'${d.student.status==='active'?'blocked':'active'}')">${d.student.status==='active'?'Block student':'Activate student'}</button><button class="btn small orange" onclick="resetStudentPassword(${id},'${esc(d.student.full_name).replaceAll("'","&#39;")}')">Change password</button><button class="btn small danger" onclick="deleteStudent(${id},${Number(d.certificateCount||0)})">Delete student</button></div><p class="small-text muted" style="margin-top:10px">Certificates: <b>${Number(d.certificateCount||0)}</b> · Certificates are deleted separately.</p></div><div class="card"><b>Exam results</b>${d.results.length?`<div class="stack" style="margin-top:12px">${d.results.map(r=>`<div class="statline"><span>${esc(r.title)}</span><span>${Number(r.percentage).toFixed(1)}%</span></div>`).join('')}</div>`:`<p class="muted">No results yet.</p>`}</div></div>`)}
async function resetStudentPassword(id,name){openModal(`<div class="modal-head"><div><div class="eyebrow">Account security</div><h2>Change student password</h2><p class="muted">Set a new password for ${esc(name)}. The student will need to sign in again.</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveStudentPassword(event,${id})"><div class="field"><label>New password</label><input name="newPassword" type="password" minlength="8" maxlength="128" autocomplete="new-password" required placeholder="At least 8 characters"></div><div class="field"><label>Confirm password</label><input name="confirmPassword" type="password" minlength="8" maxlength="128" autocomplete="new-password" required placeholder="Repeat the new password"></div><div class="card security-note"><b>Admin action</b><span>The student's existing sessions will be signed out after the password is changed.</span></div><div class="actions"><button type="button" class="btn ghost" onclick="studentDetail(${id})">Cancel</button><button class="btn orange">Update password</button></div></form>`)}
async function saveStudentPassword(e,id){e.preventDefault();const fd=new FormData(e.target),newPassword=String(fd.get('newPassword')||''),confirmPassword=String(fd.get('confirmPassword')||'');if(newPassword!==confirmPassword){showError('The two passwords do not match. Please enter the same password in both fields.','Passwords do not match');return}try{await api(`/api/admin/students/${id}/reset-password`,{method:'POST',body:JSON.stringify({newPassword})});closeModal();showToast('Student password updated');studentDetail(id)}catch(x){showError(x.message||'Unable to update password','Password update failed')}}
async function toggleStudent(id,status){try{await api(`/api/admin/students/${id}`,{method:'PATCH',body:JSON.stringify({status})});closeModal();showToast('Student status updated');adminTab('students')}catch(x){showError(x.message||'Unable to update student status','Student update failed')}}
async function deleteStudent(id,certificateCount){if(Number(certificateCount)>0){showError('Delete this student’s certificates first. Certificate deletion is a separate action.','Student cannot be deleted yet');return}if(!confirm('Delete this student account and its exam history? This action cannot be undone.'))return;try{await api(`/api/admin/students/${id}`,{method:'DELETE'});closeModal();showToast('Student deleted');adminTab('students')}catch(x){showError(x.message||'Unable to delete student','Student deletion failed')}}
async function adminExams(el){const rows=await api('/api/admin/exams');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Assessment design</div><h1>Exams</h1></div><button class="btn orange" onclick="examForm()">+ New Exam</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Exam</th><th>Type / Course</th><th>Questions</th><th>Duration</th><th>Availability</th><th>Status</th><th>Device</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.title)}</b><div class="small-text muted">${esc(r.description||'')}</div></td><td><span class="pill">${r.exam_type==='course'?'Course Exam':'Skill Assessment'}</span>${r.exam_type==='course'?`<div class="small-text muted">${esc(r.course_title||'Course not linked')}</div>`:''}</td><td>${r.question_count}</td><td>${r.duration_minutes} min</td><td><div class="schedule-cell"><b>${r.available_from?esc(fmtSchedule(r.available_from)):'Immediately'}</b><span>${r.expires_at?`Until ${esc(fmtSchedule(r.expires_at))}`:'No expiry'}</span></div></td><td><span class="pill">${r.status}</span></td><td>${Number(r.desktop_required)===1?'<span class="device-badge">Desktop</span>':'<span class="muted small-text">Any device</span>'}</td><td><div class="actions"><button class="btn small ghost" onclick="questionManager(${r.id},'${esc(r.title).replaceAll("'","&#39;")}')">Questions</button><button class="btn small ghost" onclick='examForm(${JSON.stringify(r).replace(/'/g,"&#39;")})'>Edit</button><button class="btn small danger" onclick="deleteExam(${r.id})">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="8" class="empty">No exams.</td></tr>`}</tbody></table></div></div>`}
function attachmentRows(exam){let raw=exam?.attachments||exam?.attachments_json||[];let arr=[];try{arr=Array.isArray(raw)?raw:JSON.parse(raw||'[]')}catch{};if(!arr.length)arr=[{}];return arr.map(attachmentRow).join('')}
function attachmentRow(a={}){return `<div class="attachment-row"><div class="field"><label>File name</label><input name="attachmentName" maxlength="200" placeholder="e.g. Excel template" value="${esc(a?.name||'')}"></div><div class="field"><label>File URL</label><input name="attachmentUrl" type="url" maxlength="2000" placeholder="https://..." value="${esc(a?.url||'')}"></div><button type="button" class="btn small ghost" onclick="this.closest('.attachment-row').remove()">Remove</button></div>`}
function addAttachmentRow(){document.getElementById('attachmentRows')?.insertAdjacentHTML('beforeend',attachmentRow())}
async function examForm(exam=null){let skills=[];try{skills=JSON.parse(exam?.certificate_skills_json||'[]')}catch{}let courses=[];try{courses=await api('/api/admin/learning/courses')}catch(e){}const courseExam=exam?.exam_type==='course';const startValue=localInputValue(exam?.available_from);const hours=exam?.available_from&&exam?.expires_at?Math.max(1,Math.round((Date.parse(exam.expires_at)-Date.parse(exam.available_from))/3600000)):24;openModal(`<div class="modal-head"><div><div class="eyebrow">${exam?'Edit exam':'Create exam'}</div><h2>${exam?'Update exam':'New exam'}</h2><p class="muted">One exam system, with separate visibility for skill assessments and course final exams.</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveExam(event,${exam?.id||0})"><div class="field"><label>Exam type</label><select name="examType" id="examTypeSelect" onchange="toggleExamCourseField()"><option value="assessment" ${!courseExam?'selected':''}>Skill Assessment — appears in Assessments</option><option value="course" ${courseExam?'selected':''}>Course Exam — appears only inside its course</option></select><small class="muted">Course exams use the same question bank, timer, scoring and results engine, but are hidden from the general Assessments list.</small></div><div class="field" id="examCourseField" style="${courseExam?'':'display:none'}"><label>Linked course</label><select name="courseId" id="examCourseSelect"><option value="">Choose course</option>${courses.map(c=>`<option value="${c.id}" ${Number(exam?.course_id)===Number(c.id)?'selected':''}>${esc(c.title)}</option>`).join('')}</select><small class="muted">This exam will be added as the final module inside the selected course.</small></div><div class="field"><label>Title</label><input name="title" required value="${esc(exam?.title||'')}"></div><div class="field"><label>Description</label><textarea name="description" rows="3">${esc(exam?.description||'')}</textarea></div><div class="two-col"><div class="field"><label>Duration (minutes)</label><input name="durationMinutes" type="number" min="1" max="600" required value="${exam?.duration_minutes||30}"></div><div class="field"><label>Passing percentage</label><input name="passingPercentage" type="number" min="0" max="100" step="0.1" required value="${exam?.passing_percentage??50}"></div></div><div class="field"><label>Status</label><select name="status"><option value="active" ${exam?.status==='active'?'selected':''}>Active</option><option value="inactive" ${exam?.status!=='active'?'selected':''}>Inactive</option></select></div><div class="schedule-box"><div class="eyebrow">Exam availability</div><h3>Set when students can access it</h3><div class="two-col"><div class="field"><label>Start date & time</label><input name="availableFrom" type="datetime-local" value="${startValue}"><small class="muted">Leave empty to make it available immediately.</small></div><div class="field"><label>Availability window (hours)</label><input name="availabilityHours" type="number" min="1" max="720" step="1" value="${hours}"><small class="muted">Example: 24 means the exam closes 24 hours after the start time.</small></div></div><div class="schedule-preview" id="schedulePreview"></div></div><label class="switch-field"><input type="checkbox" name="desktopRequired" ${Number(exam?.desktop_required)===1?'checked':''}><span><b>Require desktop / laptop</b><small>Show a warning and prevent this exam from starting on phones and tablets.</small></span></label><div class="card" style="padding:18px;background:var(--surface2)"><div class="eyebrow">Certificate settings</div><h3 style="margin:5px 0 12px">Assessment credential</h3><label class="switch-field"><input type="checkbox" name="certificateEnabled" ${Number(exam?.certificate_enabled??1)===1?'checked':''}><span><b>Enable automatic assessment certificate</b><small>Only applies to Skill Assessments. Course Exams issue the existing course certificate after a pass and course completion.</small></span></label><div class="two-col"><div class="field"><label>Certificate title</label><input name="certificateTitle" value="${esc(exam?.certificate_title||'')}"></div><div class="field"><label>Issued by</label><input name="certificateIssuedBy" value="${esc(exam?.certificate_issued_by||'Ahmed Elsheshtawy')}"></div><div class="field"><label>Type</label><input name="certificateType" value="${esc(exam?.certificate_type||'Training')}"></div><div class="field"><label>Level</label><input name="certificateLevel" value="${esc(exam?.certificate_level||'Intermediate')}"></div><div class="field"><label>Format</label><input name="certificateFormat" value="${esc(exam?.certificate_format||'Online')}"></div><div class="field"><label>Duration</label><input name="certificateDuration" placeholder="30 hours" value="${esc(exam?.certificate_duration||'')}"></div></div><div class="field"><label>Description</label><textarea name="certificateDescription" rows="5" placeholder="Describe what the student trained on, learned or successfully completed.">${esc(exam?.certificate_description||'')}</textarea></div><div class="field"><label>Skills</label><input name="certificateSkills" value="${esc(skills.join(', '))}" placeholder="Planning, Project Management, Risk Management"><small class="muted">Separate skills with commas.</small></div></div><div class="card" style="padding:16px;background:var(--surface2)"><div class="eyebrow">Question resources</div><p class="small-text muted" style="margin:6px 0 0">Add files inside each question. A file will appear only with the question it belongs to.</p></div><button class="btn orange">Save Exam</button></form>`);updateSchedulePreview();const f=document.querySelector('#modal form');f?.querySelector('[name=availableFrom]')?.addEventListener('input',updateSchedulePreview);f?.querySelector('[name=availabilityHours]')?.addEventListener('input',updateSchedulePreview)}
function toggleExamCourseField(){const type=document.getElementById('examTypeSelect')?.value;const field=document.getElementById('examCourseField');const select=document.getElementById('examCourseSelect');if(field)field.style.display=type==='course'?'':'none';if(select)select.required=type==='course'}
function updateSchedulePreview(){const f=document.querySelector('#modal form');if(!f)return;const start=f.querySelector('[name=availableFrom]')?.value,h=Number(f.querySelector('[name=availabilityHours]')?.value),el=document.getElementById('schedulePreview');if(!el)return;if(!start){el.innerHTML='<b>Availability:</b> Immediately, with no automatic expiry.';return}const d=new Date(start);if(Number.isNaN(d.getTime())||!Number.isFinite(h)||h<1){el.textContent='Enter a valid start date and availability window.';return}const end=new Date(d.getTime()+h*3600000);el.innerHTML=`<b>Starts:</b> ${esc(d.toLocaleString([], {dateStyle:'medium',timeStyle:'short'}))}<br><b>Expires:</b> ${esc(end.toLocaleString([], {dateStyle:'medium',timeStyle:'short'}))}`}
async function saveExam(e,id){e.preventDefault();const fd=new FormData(e.target);const start=fd.get('availableFrom');const hours=fd.get('availabilityHours');const data={title:fd.get('title'),description:fd.get('description'),examType:fd.get('examType')||'assessment',courseId:fd.get('examType')==='course'?(fd.get('courseId')||null):null,durationMinutes:fd.get('durationMinutes'),passingPercentage:fd.get('passingPercentage'),status:fd.get('status'),desktopRequired:fd.get('desktopRequired')==='on',availableFrom:start?new Date(start).toISOString():'',availabilityHours:hours,certificateEnabled:fd.get('certificateEnabled')==='on',certificateTitle:fd.get('certificateTitle'),certificateIssuedBy:fd.get('certificateIssuedBy'),certificateType:fd.get('certificateType'),certificateLevel:fd.get('certificateLevel'),certificateFormat:fd.get('certificateFormat'),certificateDuration:fd.get('certificateDuration'),certificateDescription:fd.get('certificateDescription'),certificateSkills:String(fd.get('certificateSkills')||'').split(',').map(x=>x.trim()).filter(Boolean)};try{await api(id?`/api/admin/exams/${id}`:'/api/admin/exams',{method:id?'PUT':'POST',body:JSON.stringify(data)});closeModal();showToast('Exam saved');adminTab('exams')}catch(x){showError(x.message)}}
async function deleteExam(id){if(!confirm('Delete this exam and all its questions/results?'))return;try{await api(`/api/admin/exams/${id}`,{method:'DELETE'});showToast('Exam deleted');adminTab('exams')}catch(x){showError(x.message)}}
async function questionManager(examId,title){const qs=await api(`/api/admin/exams/${examId}/questions`);openModal(`<div class="modal-head"><div><div class="eyebrow">Question bank</div><h2>${esc(title)}</h2><p class="muted">Add questions manually or import up to 200 questions from Excel.</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="actions" style="margin-bottom:15px;flex-wrap:wrap"><button class="btn orange" onclick="questionForm(${examId},null,'${esc(title).replaceAll("'","&#39;")}')">+ Add Question</button><button class="btn ghost" onclick="questionImportForm(${examId},'${esc(title).replaceAll("'","&#39;")}')">Import Excel</button><a class="btn ghost" href="/question-import-template.xlsx" download>Download Template</a></div><div class="stack">${qs.map((q,i)=>{const files=Array.isArray(q.attachments)?q.attachments:[];return `<div class="card"><div class="small-text muted">Question ${i+1} · ${q.points} point${q.points==1?'':'s'} · Correct answer ${q.correct_answer}</div><b>${esc(q.question_text)}</b><p class="small-text muted">A. ${esc(q.option_a)} · B. ${esc(q.option_b)} · C. ${esc(q.option_c)} · D. ${esc(q.option_d)}</p>${files.length?`<div class="small-text"><b>Resources:</b> ${files.map(f=>esc(f.name)).join(' · ')}</div>`:''}<div class="actions"><button class="btn small ghost" onclick='questionForm(${examId},${JSON.stringify(q).replace(/'/g,"&#39;")},"${esc(title).replaceAll('"','&quot;')}")'>Edit</button><button class="btn small danger" onclick="deleteQuestion(${q.id},${examId},'${esc(title).replaceAll("'","&#39;")}')">Delete</button></div></div>`}).join('')||`<div class="empty">No questions yet.</div>`}</div>`)}
async function loadXLSX(){if(window.XLSX)return window.XLSX;if(window.__xlsxPromise)return window.__xlsxPromise;window.__xlsxPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js';script.onload=()=>resolve(window.XLSX);script.onerror=()=>reject(new Error('Could not load the Excel reader. Check your internet connection and try again.'));document.head.appendChild(script)});return window.__xlsxPromise}
function questionImportForm(examId,title){openModal(`<div class="modal-head"><div><div class="eyebrow">Bulk question import</div><h2>Import questions from Excel</h2><p class="muted">Use the template columns: Question, Option A, Option B, Option C, Option D, Correct Answer, Points, Sort Order.</p></div><button class="icon-btn" onclick="questionManager(${examId},'${esc(title).replaceAll("'","&#39;")}')">×</button></div><div class="card import-help"><b>How it works</b><ol class="small-text"><li>Download the template.</li><li>Fill one question per row.</li><li>Save as .xlsx.</li><li>Choose the file below and review the detected rows.</li></ol></div><form class="form" onsubmit="previewQuestionImport(event,${examId},'${esc(title).replaceAll("'","&#39;")}')"><div class="field"><label>Excel file (.xlsx / .xls)</label><input id="questionExcelFile" name="excelFile" type="file" accept=".xlsx,.xls" required></div><button class="btn orange">Read Excel</button></form>`)}
function normalizeExcelHeader(v){return String(v??'').trim().toLowerCase().replace(/[\s_-]+/g,'')}
function excelValue(row,keys){for(const key of keys){const nk=normalizeExcelHeader(key);const found=Object.keys(row).find(k=>normalizeExcelHeader(k)===nk);if(found!==undefined)return row[found]}return ''}
async function previewQuestionImport(e,examId,title){e.preventDefault();const file=e.target.excelFile.files?.[0];if(!file)return;try{const XLSX=await loadXLSX();const data=await file.arrayBuffer();const wb=XLSX.read(data,{type:'array'});const ws=wb.Sheets[wb.SheetNames[0]];const rows=XLSX.utils.sheet_to_json(ws,{defval:'',raw:false});const questions=rows.map((r,i)=>({questionText:String(excelValue(r,['Question','Question Text','question_text'])).trim(),optionA:String(excelValue(r,['Option A','A','option_a'])).trim(),optionB:String(excelValue(r,['Option B','B','option_b'])).trim(),optionC:String(excelValue(r,['Option C','C','option_c'])).trim(),optionD:String(excelValue(r,['Option D','D','option_d'])).trim(),correctAnswer:String(excelValue(r,['Correct Answer','Correct','correct_answer'])).trim().toUpperCase(),points:Number(excelValue(r,['Points','points'])||1),sortOrder:Number(excelValue(r,['Sort Order','Order','sort_order'])||i+1)})).filter(q=>q.questionText||q.optionA||q.optionB||q.optionC||q.optionD);if(!questions.length)throw new Error('No question rows were found in the first sheet.');if(questions.length>200)throw new Error('Maximum 200 questions per import.');const invalid=questions.findIndex(q=>!q.questionText||!q.optionA||!q.optionB||!q.optionC||!q.optionD||!['A','B','C','D'].includes(q.correctAnswer)||!Number.isFinite(q.points)||q.points<=0||!Number.isInteger(q.sortOrder));if(invalid>=0)throw new Error(`Invalid data in imported row ${invalid+2}. Check all required columns and Correct Answer (A/B/C/D).`);openModal(`<div class="modal-head"><div><div class="eyebrow">Import preview</div><h2>${questions.length} questions detected</h2><p class="muted">Review the first few rows, then confirm the import.</p></div><button class="icon-btn" onclick="questionManager(${examId},'${esc(title).replaceAll("'","&#39;")}')">×</button></div><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>Question</th><th>A</th><th>B</th><th>C</th><th>D</th><th>Correct</th><th>Points</th></tr></thead><tbody>${questions.slice(0,8).map((q,i)=>`<tr><td>${i+1}</td><td>${esc(q.questionText)}</td><td>${esc(q.optionA)}</td><td>${esc(q.optionB)}</td><td>${esc(q.optionC)}</td><td>${esc(q.optionD)}</td><td><b>${q.correctAnswer}</b></td><td>${q.points}</td></tr>`).join('')}</tbody></table></div>${questions.length>8?`<p class="small-text muted">Showing first 8 of ${questions.length} rows.</p>`:''}<div class="actions"><button class="btn ghost" onclick="questionImportForm(${examId},'${esc(title).replaceAll("'","&#39;")}')">Back</button><button class="btn orange" onclick='confirmQuestionImport(${examId},${JSON.stringify(questions).replace(/'/g,"&#39;")},"${esc(title).replaceAll('"','&quot;')}")'>Import ${questions.length} Questions</button></div>`)}catch(x){showError(x.message||'Unable to read Excel file','Excel import failed')}}
async function confirmQuestionImport(examId,questions,title){try{const d=await api('/api/admin/questions/bulk',{method:'POST',body:JSON.stringify({examId,questions})});showToast(`${d.inserted} questions imported`);await questionManager(examId,title)}catch(x){showError(x.message||'Import failed','Import failed')}}
function questionAttachmentRows(q){let raw=q?.attachments||q?.attachments_json||[];let arr=[];try{arr=Array.isArray(raw)?raw:JSON.parse(raw||'[]')}catch{};if(!arr.length)arr=[{}];return arr.map(questionAttachmentRow).join('')}
function questionAttachmentRow(a={}){return `<div class="attachment-row question-attachment-row"><div class="field"><label>File name</label><input name="questionAttachmentName" maxlength="200" placeholder="e.g. Case study 1" value="${esc(a?.name||'')}"></div><div class="field"><label>File URL</label><input name="questionAttachmentUrl" type="url" maxlength="2000" placeholder="https://..." value="${esc(a?.url||'')}"></div><button type="button" class="btn small ghost" onclick="this.closest('.question-attachment-row').remove()">Remove</button></div>`}
function addQuestionAttachmentRow(){document.getElementById('questionAttachmentRows')?.insertAdjacentHTML('beforeend',questionAttachmentRow())}
function questionForm(examId,q,title){openModal(`<div class="modal-head"><div><div class="eyebrow">${q?'Edit question':'Add question'}</div><h2>${esc(title)}</h2></div><button class="icon-btn" onclick="questionManager(${examId},'${esc(title).replaceAll("'","&#39;")}')">×</button></div><form class="form" onsubmit="saveQuestion(event,${examId},${q?.id||0},'${esc(title).replaceAll("'","&#39;")}')"><div class="field"><label>Question</label><textarea name="questionText" rows="4" required>${esc(q?.question_text||'')}</textarea></div><div class="two-col"><div class="field"><label>Option A</label><input name="optionA" required value="${esc(q?.option_a||'')}"></div><div class="field"><label>Option B</label><input name="optionB" required value="${esc(q?.option_b||'')}"></div><div class="field"><label>Option C</label><input name="optionC" required value="${esc(q?.option_c||'')}"></div><div class="field"><label>Option D</label><input name="optionD" required value="${esc(q?.option_d||'')}"></div></div><div class="two-col"><div class="field"><label>Correct answer</label><select name="correctAnswer">${['A','B','C','D'].map(x=>`<option ${q?.correct_answer===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Points</label><input name="points" type="number" min="0.1" step="0.1" value="${q?.points||1}"></div></div><div class="field"><label>Sort order</label><input name="sortOrder" type="number" value="${q?.sort_order||0}"></div><div class="attachment-admin"><div class="section-head" style="margin:8px 0 12px"><div><div class="eyebrow">Question resources</div><h3 style="margin:4px 0 0">Files for this question</h3></div><button type="button" class="btn small ghost" onclick="addQuestionAttachmentRow()">+ Add file</button></div><p class="small-text muted">These files will appear only with this specific question during the exam.</p><div id="questionAttachmentRows" class="attachment-rows">${questionAttachmentRows(q)}</div></div><button class="btn orange">Save Question</button></form>`)}
async function saveQuestion(e,examId,id,title){e.preventDefault();const fd=new FormData(e.target);const names=fd.getAll('questionAttachmentName'),urls=fd.getAll('questionAttachmentUrl');const data=Object.fromEntries(fd);data.examId=examId;data.attachments=names.map((name,i)=>({name:String(name||'').trim(),url:String(urls[i]||'').trim()})).filter(x=>x.name&&x.url);try{await api(id?`/api/admin/questions/${id}`:'/api/admin/questions',{method:id?'PUT':'POST',body:JSON.stringify(data)});await questionManager(examId,title);showToast('Question saved')}catch(x){showError(x.message)}}
async function deleteQuestion(id,examId,title){if(!confirm('Delete this question?'))return;try{await api(`/api/admin/questions/${id}`,{method:'DELETE'});await questionManager(examId,title);showToast('Question deleted')}catch(x){showError(x.message||'Unable to delete question','Question deletion failed')}}

async function adminCertificates(el){
  try{
    const [rows,learningRows]=await Promise.all([api('/api/admin/certificates'),api('/api/admin/learning/certificates').catch(()=>[])]);
    const pending=rows.filter(c=>['not_sent','failed'].includes(String(c.email_status||'not_sent'))).length;
    const sent=rows.filter(c=>c.email_status==='sent').length;
    const statusLabel=c=>{const st=c.email_status||'not_sent';if(st==='sent')return `<span class="pill pass">Sent</span>`;if(st==='failed')return `<span class="pill fail">Failed</span>`;if(st==='sending')return `<span class="pill">Sending</span>`;return `<span class="pill">Not sent</span>`};
    el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Credentials</div><h1>Certificates</h1><p class="muted">Manage issued credentials, verification links and certificate email delivery.</p></div><div class="actions"><button class="btn orange" onclick="sendPendingCertificateEmails()">Send pending emails (${pending})</button></div></div><div class="grid grid-3" style="margin-bottom:14px"><div class="card"><span class="small-text muted">Total certificates</span><h2 style="margin:6px 0 0">${rows.length}</h2></div><div class="card"><span class="small-text muted">Emails sent</span><h2 style="margin:6px 0 0">${sent}</h2></div><div class="card"><span class="small-text muted">Need attention</span><h2 style="margin:6px 0 0">${pending}</h2></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Certificate</th><th>Student</th><th>Exam</th><th>Score</th><th>Issued</th><th>Email</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><b>${esc(c.certificate_number)}</b></td><td><b>${esc(c.student_name)}</b><div class="small-text muted">${esc(c.student_email||'No email')}</div></td><td>${esc(c.exam_title)}</td><td>${Number(c.percentage).toFixed(1)}%</td><td>${fmtDate(c.issued_at)}</td><td>${statusLabel(c)}<div class="small-text muted">Attempts: ${Number(c.email_attempts||0)}${c.email_sent_at?` · ${fmtDate(c.email_sent_at)}`:''}</div>${c.email_error?`<div class="small-text" style="color:#c33;margin-top:3px">${esc(c.email_error)}</div>`:''}</td><td><span class="pill ${c.status==='valid'?'pass':'fail'}">${c.status}</span></td><td><div class="actions"><button class="btn small ghost" onclick="certificateDetail('${esc(c.id).replaceAll("'","&#39;")}')">Details</button><a class="btn small ghost" href="/verify/${encodeURIComponent(c.certificate_number)}" target="_blank" rel="noopener">View</a>${c.student_email?`<button class="btn small ${c.email_status==='sent'?'ghost':'orange'}" onclick="sendCertificateEmailAdmin('${esc(c.id).replaceAll("'","&#39;")}',${c.email_status==='sent'?'true':'false'})">${c.email_status==='sent'?'Resend':'Send email'}</button>`:''}${c.status==='valid'?`<button class="btn small danger" onclick="revokeCertificate(${c.id})">Revoke</button>`:`<button class="btn small orange" onclick="restoreCertificate(${c.id})">Restore</button>`}<button class="btn small danger" onclick="deleteCertificate('${esc(c.id).replaceAll("'","&#39;")}')">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="8" class="empty">No certificates issued yet.</td></tr>`}</tbody></table></div></div><div class="dashboard-head" style="margin-top:28px"><div><div class="eyebrow">Course & challenge credentials</div><h2>Learning Certificates</h2><p class="muted">Issued when a course or challenge enrollment is marked completed.</p></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Certificate ID</th><th>Student</th><th>Achievement</th><th>Type</th><th>Issued</th><th>Status</th><th>Actions</th></tr></thead><tbody>${learningRows.map(c=>`<tr><td><b>${esc(c.certificate_number)}</b></td><td>${esc(c.student_name)}<div class="small-text muted">${esc(c.student_email||'')}</div></td><td>${esc(c.title)}</td><td>${esc(c.source_type)}</td><td>${fmtDate(c.issued_at)}</td><td><span class="pill ${c.status==='valid'?'pass':'fail'}">${esc(c.status)}</span></td><td><div class="actions"><a class="btn small ghost" href="/verify/${encodeURIComponent(c.certificate_number)}" target="_blank" rel="noopener">View</a><button class="btn small ${c.status==='valid'?'danger':'orange'}" onclick="toggleLearningCertificate(${c.id},'${c.status==='valid'?'revoked':'valid'}')">${c.status==='valid'?'Revoke':'Restore'}</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No course or challenge certificates issued yet. Complete an enrollment from Admin → Enrollments to issue one.</td></tr>'}</tbody></table></div></div>`;
  }catch(x){showError(x.message||'Could not load certificates','Certificates unavailable')}
}
async function sendCertificateEmailAdmin(id,force=false){
  try{if(force&&!confirm('Send this certificate email again?'))return;showToast('Sending certificate email...');const r=await api(`/api/admin/certificates/${encodeURIComponent(id)}/send-email`,{method:'POST'});if(r.sent){showToast('Certificate email sent successfully.')}else{showError(r.error||r.reason||'The email could not be sent. Check Gmail relay settings.','Certificate email not sent')}await loadAdminTab();}catch(x){showError(x.message||'Could not send certificate email','Certificate email failed')}}
async function sendPendingCertificateEmails(){
  try{if(!confirm('Send emails for all certificates that are not sent or previously failed?'))return;showToast('Sending pending certificate emails...');const r=await api('/api/admin/certificates/send-pending',{method:'POST'});showToast(`Finished: ${Number(r.sent||0)} sent, ${Number(r.failed||0)} failed.`);await loadAdminTab();}catch(x){showError(x.message||'Could not send pending certificate emails','Certificate email delivery failed')}}

async function certificateDetail(id){try{const c=await api(`/api/admin/certificates/${encodeURIComponent(id)}`);const score=Number(c.score||0),total=Number(c.total_points||0),percentage=Number(c.percentage||0);openModal(`<div class="modal-head"><div><div class="eyebrow">Certificate details</div><h2>${esc(c.certificate_number)}</h2><p class="muted">Full certificate record and student assessment score.</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="grid grid-2"><div class="card"><div class="eyebrow">Student</div><h3 style="margin:5px 0 8px">${esc(c.student_name)}</h3><p class="muted">${esc(c.student_id||'')} · ${esc(c.student_email||'')}</p></div><div class="card"><div class="eyebrow">Assessment</div><h3 style="margin:5px 0 8px">${esc(c.exam_title||'Assessment')}</h3><p class="muted">${esc(c.title||'Certificate')}</p></div></div><div class="grid grid-2" style="margin-top:14px"><div class="card"><div class="eyebrow">Score</div><h2 style="margin:6px 0 0">${score.toFixed(1)}${total?` / ${total.toFixed(1)}`:''}</h2></div><div class="card"><div class="eyebrow">Percentage</div><h2 style="margin:6px 0 0">${percentage.toFixed(1)}%</h2></div></div><div class="card" style="margin-top:14px"><div class="grid grid-2"><div><span class="small-text muted">Status</span><p><span class="pill ${c.status==='valid'?'pass':'fail'}">${esc(c.status)}</span></p></div><div><span class="small-text muted">Issued</span><p><b>${fmtDate(c.issued_at)}</b></p></div><div><span class="small-text muted">Type</span><p><b>${esc(c.type||'Training')}</b></p></div><div><span class="small-text muted">Level</span><p><b>${esc(c.level||'Intermediate')}</b></p></div></div></div><div class="actions" style="margin-top:16px"><a class="btn small ghost" href="/verify/${encodeURIComponent(c.certificate_number)}" target="_blank" rel="noopener">View certificate</a>${c.status==='valid'?`<button class="btn small danger" onclick="revokeCertificate('${esc(c.id).replaceAll("'","&#39;")}')">Revoke</button>`:`<button class="btn small orange" onclick="restoreCertificate('${esc(c.id).replaceAll("'","&#39;")}')">Restore</button>`}<button class="btn small danger" onclick="deleteCertificate('${esc(c.id).replaceAll("'","&#39;")}')">Delete certificate</button></div>`)}catch(x){showError(x.message||'Could not load certificate details','Certificate details unavailable')}}
async function revokeCertificate(id){const reason=prompt('Reason for revocation (optional):','');if(reason===null)return;try{await api(`/api/admin/certificates/${id}/revoke`,{method:'POST',body:JSON.stringify({reason})});showToast('Certificate revoked');adminTab('certificates')}catch(x){showError(x.message)}}
async function restoreCertificate(id){if(!confirm('Restore this certificate and mark it valid again?'))return;try{await api(`/api/admin/certificates/${id}/restore`,{method:'POST'});showToast('Certificate restored');adminTab('certificates')}catch(x){showError(x.message)}}
async function deleteCertificate(id){if(!confirm('Delete this certificate permanently? This does not delete the student account or exam result.'))return;try{await api(`/api/admin/certificates/${encodeURIComponent(id)}`,{method:'DELETE'});showToast('Certificate deleted');adminTab('certificates')}catch(x){showError(x.message||'Unable to delete certificate','Certificate deletion failed')}}
async function adminResults(el){try{const [rows,d]=await Promise.all([api('/api/admin/results'),api('/api/admin/results/stats')]);el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Performance</div><h1>Results</h1><p class="muted">Track completion, scores and pass performance at a glance.</p></div><div class="toolbar"><input id="resultSearch" placeholder="Search results…" oninput="searchResults()"></div></div><div class="kpis results-kpis"><div class="card kpi"><div class="kpi-label">Total results</div><div class="num">${d.total}</div><small>Completed assessments</small></div><div class="card kpi"><div class="kpi-label">Passed</div><div class="num success-text">${d.passed}</div><small>${d.passRate.toFixed(1)}% pass rate</small></div><div class="card kpi"><div class="kpi-label">Not passed</div><div class="num danger-text">${d.failed}</div><small>Needs improvement</small></div><div class="card kpi"><div class="kpi-label">Average</div><div class="num">${d.average.toFixed(1)}%</div><small>Overall performance</small></div><div class="card kpi"><div class="kpi-label">Highest</div><div class="num">${d.highest.toFixed(1)}%</div><small>Best result</small></div><div class="card kpi"><div class="kpi-label">Lowest</div><div class="num">${d.lowest.toFixed(1)}%</div><small>Lowest result</small></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Exam</th><th>Score</th><th>Percentage</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody id="results-body">${resultRows(rows)}</tbody></table></div></div>`}catch(x){showError(x.message||'Could not load results','Results unavailable')}}
function resultRows(rows){return rows.map(r=>`<tr><td><b>${esc(r.student_id)}</b><div class="small-text muted">${esc(r.full_name)}</div></td><td>${esc(r.title)}</td><td>${r.score}/${r.total_points}</td><td>${Number(r.percentage).toFixed(1)}%</td><td><span class="pill ${r.passed?'pass':'fail'}">${r.passed?'Passed':'Not passed'}</span></td><td>${fmtDate(r.created_at)}</td><td><button class="btn small ghost" onclick="resultDetail(${r.id})">View</button></td></tr>`).join('')||`<tr><td colspan="7" class="empty">No results.</td></tr>`}
let resultTimer;async function searchResults(){clearTimeout(resultTimer);resultTimer=setTimeout(async()=>{try{const q=document.getElementById('resultSearch').value;const rows=await api('/api/admin/results?q='+encodeURIComponent(q));document.getElementById('results-body').innerHTML=resultRows(rows)}catch(x){showError(x.message||'Could not search results','Search failed')}},250)}
async function resultDetail(id){
  const d=await api(`/api/admin/results/${id}`);
  const optionKeys=['A','B','C','D'];
  const answerCards=d.answers.map((a,i)=>{
    const correct=Number(a.is_correct)===1;
    const selected=String(a.selected_answer||'').toUpperCase();
    const correctKey=String(a.correct_answer||'').toUpperCase();
    const optionHtml=optionKeys.map(k=>{
      const value=a['option_'+k.toLowerCase()]||'';
      const isSelected=selected===k;
      const isCorrect=correctKey===k;
      let cls='answer-option';
      if(isCorrect) cls+=' is-correct';
      if(isSelected&&!isCorrect) cls+=' is-selected-wrong';
      return `<div class="${cls}"><span class="answer-option-key">${k}</span><span>${esc(value)}</span>${isCorrect?'<b class="answer-option-label">Correct</b>':''}${isSelected&&!isCorrect?'<b class="answer-option-label">Student choice</b>':''}</div>`;
    }).join('');
    return `<article class="answer-review-card ${correct?'answer-correct':'answer-wrong'}"><div class="answer-review-head"><div><span class="answer-review-status">${correct?'✓ Correct':'✕ Incorrect'}</span><b>${i+1}. ${esc(a.question_text)}</b></div><span class="pill ${correct?'pass':'fail'}">${correct?'Correct':'Incorrect'}</span></div><div class="answer-review-meta"><span>Student answer: <b>${esc(selected||'No answer')}</b></span><span>Correct answer: <b>${esc(correctKey||'—')}</b></span><span>Points: <b>${Number(a.points_earned||0)} / ${Number(a.points||0)}</b></span></div>${!correct?`<div class="answer-options">${optionHtml}</div>`:''}</article>`;
  }).join('');
  openModal(`<div class="modal-head"><div><div class="eyebrow">Result detail</div><h2>${esc(d.result.title)}</h2><p class="muted">${esc(d.result.student_id)} · ${esc(d.result.full_name)}</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="grid grid-3"><div class="card"><b>Score</b><div class="score" style="font-size:35px">${Number(d.result.percentage).toFixed(1)}%</div></div><div class="card"><b>Points</b><p>${d.result.score} / ${d.result.total_points}</p></div><div class="card"><b>Status</b><p class="${d.result.passed?'success-text':'danger-text'}">${d.result.passed?'Passed':'Not passed'}</p></div></div><div class="stack result-answer-review">${answerCards||'<div class="card empty">No answers are available for this result.</div>'}</div>`);
}
async function adminAdmins(el){const rows=await api('/api/admin/admins');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Access control</div><h1>Admin users</h1></div><button class="btn orange" onclick="adminForm()">+ Add Admin</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Username</th><th>Role</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.username)}</b></td><td>${esc(r.role)}</td><td><span class="pill">${r.status}</span></td><td>${fmtDate(r.created_at)}</td><td>${r.id!==undefined?`<button class="btn small ghost" onclick="toggleAdmin(${r.id},'${r.status==='active'?'blocked':'active'}')">${r.status==='active'?'Block':'Activate'}</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`}
function adminForm(){openModal(`<div class="modal-head"><div><div class="eyebrow">Access control</div><h2>Add admin</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveAdmin(event)"><div class="field"><label>Username</label><input name="username" pattern="[A-Za-z0-9._\-]{3,80}" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" required></div><div class="field"><label>Role</label><select name="role"><option value="admin">Admin</option><option value="super_admin">Super admin</option></select></div><button class="btn orange">Create Admin</button></form>`)}
async function saveAdmin(e){e.preventDefault();try{await api('/api/admin/admins',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();showToast('Admin created');adminTab('admins')}catch(x){showError(x.message)}}
async function toggleAdmin(id,status){try{await api(`/api/admin/admins/${id}`,{method:'PATCH',body:JSON.stringify({status})});showToast('Admin status updated');adminTab('admins')}catch(x){showError(x.message||'Unable to update admin status','Admin update failed')}}
function openModal(html){const d=document.createElement('div');d.id='modal';d.className='modal-backdrop';d.innerHTML=`<div class="modal">${html}</div>`;document.body.appendChild(d)}function closeModal(){document.getElementById('modal')?.remove()}
function toggleLang(){state.lang=state.lang==='en'?'ar':'en';localStorage.setItem('exam_lang',state.lang);document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';render()}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('exam_theme',state.theme);applyTheme();render()}
function applyTheme(){document.body.classList.toggle('dark-mode',state.theme==='dark');document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr'}
function toggleMobileMenu(){const panel=document.getElementById('mobileNavPanel'),btn=document.getElementById('mobileMenuBtn');if(!panel||!btn)return;const open=panel.classList.toggle('is-open');btn.classList.toggle('is-open',open);btn.setAttribute('aria-expanded',String(open));document.body.classList.toggle('mobile-menu-open',open)}
function closeMobileMenu(){const panel=document.getElementById('mobileNavPanel'),btn=document.getElementById('mobileMenuBtn');if(panel)panel.classList.remove('is-open');if(btn){btn.classList.remove('is-open');btn.setAttribute('aria-expanded','false')}document.body.classList.remove('mobile-menu-open')}

function go(v){if(v==='admin-login'){location.href='/admin';return}if(v==='home'){if(location.pathname!=='/admin.html'&&location.pathname!=='/admin')state.view='home';else state.adminTab='overview'}else if(v==='results'||v==='assessments'){state.view=state.me?.user?'results':'login';v='assessments'}else if(v==='dashboard'&&!state.me?.user){state.view='login'}else state.view=v;if(state.me?.user&&['dashboard','courses','challenges','tasks','assessments','certificates'].includes(v)){const path=v==='dashboard'?'/dashboard':`/${v}`;if(location.pathname!==path)history.pushState({view:v},'',path)}if(v!=='exam')clearInterval(state.timer);render()}
window.addEventListener('popstate',()=>location.reload());
window.go=go;window.scrollToLearning=scrollToLearning;window.showLearningNotice=showLearningNotice;window.toggleMobileMenu=toggleMobileMenu;window.closeMobileMenu=closeMobileMenu;window.openStudentResult=openStudentResult;window.closeError=closeError;window.answerQuestion=answerQuestion;window.nextQuestion=nextQuestion;window.previousQuestion=previousQuestion;window.jumpToQuestion=jumpToQuestion;window.toggleLang=toggleLang;window.toggleTheme=toggleTheme;window.adminLogin=adminLogin;window.studentLogin=studentLogin;window.studentRegister=studentRegister;window.logout=logout;window.startExam=startExam;window.submitExam=submitExam;window.adminTab=adminTab;window.searchStudents=searchStudents;window.studentDetail=studentDetail;window.toggleStudent=toggleStudent;window.deleteStudent=deleteStudent;window.deleteCertificate=deleteCertificate;window.examForm=examForm;window.toggleExamCourseField=toggleExamCourseField;window.addAttachmentRow=addAttachmentRow;window.addQuestionAttachmentRow=addQuestionAttachmentRow;window.saveExam=saveExam;window.deleteExam=deleteExam;window.questionManager=questionManager;window.questionImportForm=questionImportForm;window.previewQuestionImport=previewQuestionImport;window.confirmQuestionImport=confirmQuestionImport;window.questionForm=questionForm;window.saveQuestion=saveQuestion;window.deleteQuestion=deleteQuestion;window.searchResults=searchResults;window.resultDetail=resultDetail;window.adminForm=adminForm;window.saveAdmin=saveAdmin;window.toggleAdmin=toggleAdmin;window.closeModal=closeModal;
boot();


