function courseMediaMarkup(lesson){
  const url=String(lesson.resource_url||'').trim();if(!url)return lesson.content?`<div class="course-text-content">${esc(lesson.content).replaceAll('\n','<br>')}</div>`:`<div class="course-player-empty"><div class="course-player-empty-icon">▤</div><h3>Lesson content is being prepared</h3><p>The lesson has been added, but its video or file has not been attached yet.</p>${lesson.content?`<div class="course-text-content">${esc(lesson.content).replaceAll('\n','<br>')}</div>`:''}</div>`;
  const safe=esc(url);const type=String(lesson.lesson_type||'text').toLowerCase();const youtube=url.match(/(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/)|youtu\.be\/)([A-Za-z0-9_-]{6,})/);const vimeo=url.match(/vimeo\.com\/(?:video\/)?(\d+)/);
  if(type==='video'&&youtube)return `<div class="af-video-player" id="af-player-${Number(lesson.id)}" data-video-id="${youtube[1]}" data-title="${esc(lesson.title)}"><div class="af-video-stage"><div class="af-video-screen" id="af-screen-${Number(lesson.id)}"><div id="af-yt-${Number(lesson.id)}"></div></div><button class="af-video-cover is-poster" id="af-cover-${Number(lesson.id)}" style="background-image:linear-gradient(180deg,rgba(8,20,16,.2),rgba(8,20,16,.82)),url(https://i.ytimg.com/vi/${youtube[1]}/hqdefault.jpg)" type="button" aria-label="تشغيل الفيديو" onclick="afVideoToggle(${Number(lesson.id)})"><span class="af-video-big-play"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14l11-7z"/></svg></span><span class="af-video-cover-meta"><b>${esc(lesson.title)}</b><small>اضغط للتشغيل</small></span></button><button class="af-video-shield" id="af-shield-${Number(lesson.id)}" type="button" aria-label="تشغيل أو إيقاف الفيديو" onclick="afVideoToggle(${Number(lesson.id)})"></button></div><div class="af-video-bar" id="af-bar-${Number(lesson.id)}"><input class="af-video-seek" id="af-seek-${Number(lesson.id)}" type="range" min="0" max="1000" value="0" aria-label="التقدم" oninput="afVideoSeek(${Number(lesson.id)},this)"><button type="button" id="af-play-${Number(lesson.id)}" aria-label="تشغيل" onclick="afVideoToggle(${Number(lesson.id)})"><svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg></button><button type="button" id="af-mute-${Number(lesson.id)}" aria-label="كتم الصوت" onclick="afVideoMute(${Number(lesson.id)})"><svg viewBox="0 0 24 24"><path d="M3 10v4h4l5 4V6L7 10H3z"/><path d="M15.5 8.5a5 5 0 010 7" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></button><input class="af-video-volume" id="af-vol-${Number(lesson.id)}" type="range" min="0" max="100" value="100" aria-label="مستوى الصوت" oninput="afVideoVolume(${Number(lesson.id)},this)"><span class="af-video-time" id="af-time-${Number(lesson.id)}">0:00 / 0:00</span><button type="button" class="af-video-speed" id="af-speed-${Number(lesson.id)}" onclick="afVideoSpeed(${Number(lesson.id)})">1x</button><button type="button" id="af-full-${Number(lesson.id)}" aria-label="شاشة كاملة" onclick="afVideoFullscreen(${Number(lesson.id)})"><svg viewBox="0 0 24 24"><path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg></button></div></div>`;
  if(type==='video'&&vimeo)return `<div class="course-media-frame"><iframe src="https://player.vimeo.com/video/${vimeo[1]}" title="${esc(lesson.title)}" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen loading="lazy"></iframe></div>`;
  if(type==='video'||/\.(mp4|webm|ogg)(\?.*)?$/i.test(url))return `<div class="course-media-frame"><video controls playsinline preload="metadata" src="${safe}">Your browser does not support embedded video. <a href="${safe}">Open video</a></video></div>`;
  if(type==='file'||/\.(pdf)(\?.*)?$/i.test(url))return `<div class="course-file-preview"><div class="course-file-icon">PDF</div><h3>${esc(lesson.title)}</h3><p>${state.lang==='ar'?'حمّل ملف الدرس من الزر أدناه.':'Download this lesson material using the button below.'}</p><div class="actions"><a class="btn orange" href="${safe}" download>${state.lang==='ar'?'تحميل الملف':'Download'} ↓</a></div></div>`;
  return `<div class="course-resource-preview"><div class="course-resource-icon">↗</div><h3>${esc(lesson.title)}</h3><p>This lesson includes an external learning resource.</p><a class="btn orange" href="${safe}" target="_blank" rel="noopener">Open resource ↗</a></div>`;
}
async function renderCoursePlayer(courseId,requestedLessonId=null){
  Object.keys(afVideoPlayers||{}).forEach(id=>{const p=afVideoPlayers[id];if(p){clearInterval(p.timer);try{p.player?.destroy()}catch(e){}delete afVideoPlayers[id]}});
  if(!state.me?.user){go('login');return}if(!courseId){renderStudentLearning();return}
  app.innerHTML=layout(`<main class="course-player-page"><div class="course-player-loading card"><span class="loading-dot"></span><p>Loading your course…</p></div></main>`);
  try{
    const d=await api(`/api/learning/courses/${courseId}`);const course=d.item;const modules=d.modules||[];const lessonRefs=d.lessons||[];let lessonDetails=[];
    for(const module of modules){const rows=lessonRefs.filter(l=>Number(l.module_id)===Number(module.id));lessonDetails.push(...rows.map(l=>({...l,module_title:module.title,module_id:Number(module.id)})));}
    const lessonResults=await Promise.all(lessonDetails.map(async l=>{try{const x=await api(`/api/learning/lessons/${l.id}`);return {...l,...x.lesson,completed:x.completed===true}}catch(e){return {...l,completed:false,loadError:e.message}}}));
    const activeLessons=lessonResults;let currentIndex=requestedLessonId?activeLessons.findIndex(l=>Number(l.id)===Number(requestedLessonId)):-1;if(currentIndex<0)currentIndex=activeLessons.findIndex(l=>!l.completed);if(currentIndex<0)currentIndex=Math.max(0,activeLessons.length-1);
    const current=activeLessons[currentIndex]||null;const completedCount=activeLessons.filter(l=>l.completed).length;const progress=activeLessons.length?Math.round(completedCount/activeLessons.length*100):0;const ar=state.lang==='ar';const resources=d.resources||[];
    const grouped=modules.map(m=>({...m,lessons:activeLessons.filter(l=>Number(l.module_id)===Number(m.id)),resources:resources.filter(r=>Number(r.module_id)===Number(m.id))}));
    const resourceIcon=r=>/pdf|file|document|download/i.test(String(r.resource_type||'')+' '+String(r.url||''))?'▤':/video|youtube|mp4/i.test(String(r.resource_type||'')+' '+String(r.url||''))?'▶':'↗';
    const resourceRows=rows=>rows.map(r=>`<a class="course-player-resource-row" href="${esc(r.url)}" target="_blank" rel="noopener"><span class="course-resource-type-icon">${resourceIcon(r)}</span><span class="course-player-lesson-copy"><b>${esc(r.title)}</b><small>${esc(r.resource_type||'download')}</small></span><span class="course-resource-open-icon">↗</span></a>`).join('');
    const sidebar=grouped.map((m,mi)=>`<details class="course-player-module" ${m.lessons.some(l=>Number(l.id)===Number(current?.id))?'open':''}><summary class="course-player-module-title"><span>${String(mi+1).padStart(2,'0')}</span><b>${esc(m.title)}</b><small>${m.lessons.filter(l=>l.completed).length}/${m.lessons.length} <i>⌄</i></small></summary><div class="course-player-lesson-list">${m.lessons.map(l=>{const idx=activeLessons.findIndex(z=>Number(z.id)===Number(l.id));const icon=String(l.lesson_type||'').toLowerCase()==='video'?'▶':String(l.lesson_type||'').toLowerCase()==='file'?'▤':'▧';return `<button class="course-player-lesson ${Number(l.id)===Number(current?.id)?'is-current':''} ${l.completed?'is-complete':''}" onclick="selectCoursePlayerLesson(${courseId},${l.id})"><span class="lesson-state lesson-type-icon">${l.completed?'✓':icon}</span><span class="course-player-lesson-copy"><b>${esc(l.title)}</b><small>${esc(l.lesson_type||'lesson')}</small></span><span class="lesson-duration">${idx+1}</span></button>`}).join('')}${m.resources.length?`<div class="course-module-resources-label">${ar?'المصادر':'Resources'}</div>${resourceRows(m.resources)}`:''}${!m.lessons.length&&!m.resources.length?'<p class="muted small-text">No lessons or resources in this module yet.</p>':''}</div></details>`).join('');
    const lessonsComplete=activeLessons.length>0&&completedCount===activeLessons.length;const hasFinalExam=!!course.final_exam_id;const examIsActive=course.final_exam_status==='active';const finalExamModule=hasFinalExam?`<details class="course-player-module course-final-exam-module"><summary class="course-player-module-title"><span>EX</span><b>${ar?'الامتحان النهائي':'Final Course Exam'}</b><small>${course.final_exam_passed?(ar?'ناجح':'Passed'):lessonsComplete?(ar?'متاح':'Ready'):(ar?'مقفل':'Locked')} <i>⌄</i></small></summary><div class="course-player-lesson-list"><div class="course-player-lesson-copy"><b>${esc(course.final_exam_title||'Final Course Exam')}</b><small>${Number(course.final_exam_duration_minutes||0)} min · ${ar?'نسبة النجاح':'Pass mark'} ${Number(course.final_exam_passing_percentage||0)}%</small></div>${course.final_exam_passed?`<div class="pill pass">✓ ${ar?'تم الاجتياز':'Successfully passed'}</div>`:!examIsActive?`<button class="btn ghost card-full-btn" disabled>${ar?'الامتحان غير متاح حاليًا':'Exam currently unavailable'}</button>`:lessonsComplete?`<button class="btn orange card-full-btn" onclick="startExam(${Number(course.final_exam_id)})">${ar?'ابدأ الامتحان':'Start final exam'} ↗</button>`:`<button class="btn ghost card-full-btn" disabled>${ar?'أكمل الدروس أولًا':'Complete all lessons first'}</button>`}</div></section>`:'';
    const moduleResourceIds=new Set(resources.filter(r=>r.module_id).map(r=>Number(r.id)));const unassignedResources=resources.filter(r=>!r.module_id);
    const sourcesSection=unassignedResources.length?`<details class="course-player-module course-sources-module"><summary class="course-player-module-title"><span>↗</span><b>${ar?'المصادر':'Sources'}</b><small>${unassignedResources.length} <i>⌄</i></small></summary><div class="course-player-lesson-list">${resourceRows(unassignedResources)}</div></details>`:'';
    app.innerHTML=layout(`<main class="course-player-page ${ar?'is-ar':''}"><div class="course-player-topline"><button class="btn ghost" onclick="renderStudentLearning()">← ${ar?'العودة إلى تعلّمي':'Back to My Learning'}</button><div class="course-player-course-meta"><span>${esc(course.category_name||'COURSE')}</span><span>${esc(course.level||'All levels')}</span></div></div><header class="course-player-heading"><div><div class="eyebrow">${ar?'مسار التعلّم':'YOUR LEARNING PATH'}</div><h1>${esc(course.title)}</h1><p>${esc(course.short_description||course.description||'')}</p></div><div class="course-player-progress"><div class="course-player-progress-top"><span>${ar?'تقدم الكورس':'COURSE PROGRESS'}</span><b>${progress}%</b></div><div class="progress-track"><span style="width:${progress}%"></span></div><small>${completedCount} / ${activeLessons.length} ${ar?'درس مكتمل':'lessons completed'}</small></div></header><div class="course-player-layout"><section class="course-player-main">${current?`<div class="course-player-current-label"><span>LESSON ${currentIndex+1} OF ${activeLessons.length}</span><span class="pill ${current.completed?'pass':''}">${current.completed?(ar?'مكتمل':'Completed'):(ar?'قيد الدراسة':'In progress')}</span></div><h2 class="course-player-lesson-title">${esc(current.title)}</h2><div class="course-player-media">${courseMediaMarkup(current)}</div>${current&&resources.some(r=>Number(r.module_id)===Number(current.module_id))?`<section class="course-player-resources course-lesson-linked-resources"><h3>${ar?'روابط وملفات الدرس':'Lesson links & files'}</h3><div>${resources.filter(r=>Number(r.module_id)===Number(current.module_id)).map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer" download><span>${/pdf|file|document|download/i.test(String(r.resource_type||'')+' '+String(r.url||''))?'▤':/video|youtube|mp4/i.test(String(r.resource_type||'')+' '+String(r.url||''))?'▶':'↗'}</span><b>${esc(r.title)}</b><small>${ar?'تحميل':'Download'} ↓</small></a>`).join('')}</div></section>`:''}${current.content&&current.resource_url?`<section class="course-player-notes"><h3>${ar?'ملاحظات الدرس':'Lesson notes'}</h3><div>${esc(current.content).replaceAll('\n','<br>')}</div></section>`:''}<div class="course-player-controls"><button class="btn ghost" onclick="selectCoursePlayerLesson(${courseId},${activeLessons[currentIndex-1]?.id||current.id})" ${currentIndex<=0?'disabled':''}>← ${ar?'الدرس السابق':'Previous lesson'}</button><div class="course-player-controls-right">${current.completed?`<span class="pill pass">✓ ${ar?'تم إكمال الدرس':'Lesson completed'}</span>`:`<button class="btn orange" onclick="completeCourseLessonInPlayer(${courseId},${current.id},${activeLessons[currentIndex+1]?.id||0})">${ar?'تم إكمال الدرس':'Mark as complete ✓'}</button>`}${current.completed&&currentIndex<activeLessons.length-1?`<button class="btn orange" onclick="selectCoursePlayerLesson(${courseId},${activeLessons[currentIndex+1].id})">${ar?'الدرس التالي':'Next lesson'} →</button>`:current.completed&&currentIndex===activeLessons.length-1?`<span class="course-finished-label">${ar?'أكملت جميع الدروس':'All lessons completed'}</span>`:''}</div></div>`:`<div class="course-player-empty"><div class="course-player-empty-icon">✓</div><h2>${ar?'المحتوى قيد الإعداد':'Course content is being prepared'}</h2><p>${ar?'لم تتم إضافة دروس لهذا الكورس بعد.':'No lessons have been added to this course yet. The course administrator can add modules and lessons from Admin → Courses → Content.'}</p></div>`}</section><aside class="course-player-sidebar"><div class="course-player-sidebar-head"><div><div class="eyebrow">COURSE CONTENT</div><h2>${ar?'محتوى الكورس':'Course curriculum'}</h2></div><span class="course-player-sidebar-count">${completedCount}/${activeLessons.length}</span></div><div class="course-player-sidebar-progress"><div class="progress-track"><span style="width:${progress}%"></span></div><small>${progress}% ${ar?'مكتمل':'complete'}</small></div><div class="course-player-modules">${sidebar||'<div class="card empty">No modules added yet.</div>'}${sourcesSection}${finalExamModule}</div></aside></div></main>`);
    if(current && String(current.lesson_type||'').toLowerCase()==='video'){
      const yt=String(current.resource_url||'').match(/(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/)|youtu\.be\/)([A-Za-z0-9_-]{6,})/);
      if(yt) afInitVideoPlayer(Number(current.id),yt[1]);
    }
  }catch(e){if(/sign in|unauthorized|enroll/i.test(e.message||'')){showError(e.message||'Enroll in this course to access lessons.');renderStudentLearning()}else showError(e.message||'Could not load course player','Course unavailable')}
}
async function selectCoursePlayerLesson(courseId,lessonId){state.coursePlayerLessonId=Number(lessonId);await renderCoursePlayer(courseId,lessonId);window.scrollTo({top:0,behavior:'smooth'})}
async function completeCourseLessonInPlayer(courseId,lessonId,nextLessonId){try{const d=await api(`/api/learning/lessons/${lessonId}/complete`,{method:'POST',body:JSON.stringify({})});showToast(`Lesson completed · Course progress ${d.progress}%`);await renderCoursePlayer(courseId,nextLessonId||lessonId)}catch(e){showError(e.message||'Could not update lesson progress','Progress update failed')}}

/* Ahmed Finance branded YouTube lesson player */
const afVideoPlayers = window.afVideoPlayers || (window.afVideoPlayers = {});
const afVideoSpeeds = [1,1.25,1.5,2,0.75];
let afYouTubeApiLoading = false, afYouTubeApiReady = false;
function afLoadYouTubeApi(){
  if(window.YT && window.YT.Player){afYouTubeApiReady=true;afInitPendingPlayers();return}
  if(afYouTubeApiLoading)return;
  afYouTubeApiLoading=true;
  const previous=window.onYouTubeIframeAPIReady;
  window.onYouTubeIframeAPIReady=function(){afYouTubeApiReady=true;if(typeof previous==='function')try{previous()}catch(e){}afInitPendingPlayers()};
  if(!document.querySelector('script[data-af-youtube-api]')){const s=document.createElement('script');s.src='https://www.youtube.com/iframe_api';s.async=true;s.dataset.afYoutubeApi='1';document.head.appendChild(s)}
}
function afInitPendingPlayers(){Object.keys(afVideoPlayers).forEach(id=>{const p=afVideoPlayers[id];if(p&&p.pending&&document.getElementById('af-yt-'+id))afCreateYouTubePlayer(Number(id))})}
function afInitVideoPlayer(id,videoId){afVideoPlayers[id]={videoId,pending:true,player:null,playing:false,played:false,playWhenReady:false,speedIndex:0,timer:null};afLoadYouTubeApi();if(afYouTubeApiReady)afCreateYouTubePlayer(id)}
function afCreateYouTubePlayer(id){
  const data=afVideoPlayers[id], target=document.getElementById('af-yt-'+id);if(!data||!target||!window.YT||!YT.Player)return;
  if(data.player){try{data.player.destroy()}catch(e){}}
  data.pending=false;
  data.player=new YT.Player(target,{host:'https://www.youtube-nocookie.com',videoId:data.videoId,playerVars:{controls:0,disablekb:1,modestbranding:1,rel:0,iv_load_policy:3,playsinline:1,fs:0,cc_load_policy:0,origin:location.origin,widget_referrer:location.origin},events:{onReady:()=>{data.ready=true;afLayoutVideo(id);afVideoTick(id);if(data.playWhenReady){data.playWhenReady=false;data.player.playVideo()}},onStateChange:e=>afVideoState(id,e.data)}});
}
function afLayoutVideo(id){const screen=document.getElementById('af-screen-'+id),frame=screen?.querySelector('iframe');if(!screen||!frame)return;frame.style.position='absolute';frame.style.inset='0';frame.style.width='100%';frame.style.height='100%';frame.style.border='0'}
function afVideoState(id,state){const d=afVideoPlayers[id];if(!d)return;d.playing=state===YT.PlayerState.PLAYING;const cover=document.getElementById('af-cover-'+id),play=document.getElementById('af-play-'+id);if(play)play.innerHTML=d.playing?'<svg viewBox="0 0 24 24"><path d="M6 5h4v14H6zM14 5h4v14h-4z"/></svg>':'<svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>';if(cover){if(d.playing){d.played=true;cover.classList.add('is-off')}else{cover.classList.remove('is-off');cover.classList.toggle('is-poster',!d.played)}}clearInterval(d.timer);if(d.playing)d.timer=setInterval(()=>afVideoTick(id),250);afVideoTick(id)}
function afFmtTime(value){const s=Math.floor(value||0),m=Math.floor(s/60),r=s%60;return m+':'+String(r).padStart(2,'0')}
function afVideoTick(id){const d=afVideoPlayers[id];if(!d?.player||!d.ready||typeof d.player.getDuration!=='function'||typeof d.player.getCurrentTime!=='function')return;try{const dur=d.player.getDuration()||0,cur=d.player.getCurrentTime()||0,seek=document.getElementById('af-seek-'+id),time=document.getElementById('af-time-'+id);if(seek&&dur){seek.value=Math.round(cur/dur*1000);seek.style.setProperty('--af-p',(seek.value/10)+'%')}if(time)time.textContent=afFmtTime(cur)+' / '+afFmtTime(dur)}catch(e){}}
function afVideoToggle(id){const d=afVideoPlayers[id];if(!d)return;try{if(!d.player||!d.ready||typeof d.player.playVideo!=='function'){d.playWhenReady=true;afLoadYouTubeApi();if(afYouTubeApiReady)afCreateYouTubePlayer(id);return}if(d.playing&&typeof d.player.pauseVideo==='function')d.player.pauseVideo();else if(typeof d.player.playVideo==='function')d.player.playVideo()}catch(e){}}
function afVideoSeek(id,input){input.style.setProperty('--af-p',(input.value/10)+'%');const d=afVideoPlayers[id];if(d?.player&&d.ready&&typeof d.player.getDuration==='function'&&typeof d.player.seekTo==='function'){const dur=d.player.getDuration()||0;if(dur)d.player.seekTo(Number(input.value)/1000*dur,true)}}
function afVideoMute(id){const d=afVideoPlayers[id];if(!d?.player||!d.ready||typeof d.player.isMuted!=='function')return;try{if(d.player.isMuted()){d.player.unMute();const v=document.getElementById('af-vol-'+id);if(v&&Number(v.value)===0)v.value=100;document.getElementById('af-mute-'+id).innerHTML='<svg viewBox="0 0 24 24"><path d="M3 10v4h4l5 4V6L7 10H3z"/><path d="M15.5 8.5a5 5 0 010 7" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>'}else{d.player.mute();document.getElementById('af-mute-'+id).innerHTML='<svg viewBox="0 0 24 24"><path d="M3 10v4h4l5 4V6L7 10H3z"/><path d="M16 9l5 6M21 9l-5 6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>'}}catch(e){}}
function afVideoVolume(id,input){input.style.setProperty('--af-p',input.value+'%');const d=afVideoPlayers[id];if(!d?.player||!d.ready||typeof d.player.setVolume!=='function')return;try{d.player.setVolume(Number(input.value));if(Number(input.value)===0)d.player.mute();else d.player.unMute();const b=document.getElementById('af-mute-'+id);if(b)b.setAttribute('aria-label',Number(input.value)===0?'تشغيل الصوت':'كتم الصوت')}catch(e){}}
function afVideoSpeed(id){const d=afVideoPlayers[id];if(!d)return;d.speedIndex=(d.speedIndex+1)%afVideoSpeeds.length;const speed=afVideoSpeeds[d.speedIndex],b=document.getElementById('af-speed-'+id);if(b)b.textContent=speed+'x';try{if(d.ready&&typeof d.player?.setPlaybackRate==='function')d.player.setPlaybackRate(speed)}catch(e){}}
function afVideoFullscreen(id){const el=document.getElementById('af-player-'+id);if(!el)return;if(document.fullscreenElement){(document.exitFullscreen||document.webkitExitFullscreen).call(document)}else{const req=el.requestFullscreen||el.webkitRequestFullscreen;if(req)req.call(el)}}
async function submitCaseStudy(e,id){e.preventDefault();const f=new FormData(e.target);try{await api(`/api/learning/cases/${id}/submit`,{method:'POST',body:JSON.stringify({response:f.get('response'),fileUrl:f.get('fileUrl')})});showToast('Your case analysis has been saved');closeModal()}catch(x){showError(x.message||'Could not submit case study','Submission failed')}}
async function renderStudentTasks(){
  const ar=state.lang==='ar';app.innerHTML=layout(`<main class="page"><div class="dashboard-head"><div><div class="eyebrow">STUDENT WORKSPACE</div><h1>${ar?'المهام المطلوبة':'My Required Tasks'}</h1><p class="muted">${ar?'كل المهام المطلوبة من الكورسات والتحديات والحالات التدريبية في مكان واحد.':'All required tasks from your courses, challenges, and case studies in one place.'}</p></div><button class="btn ghost" onclick="go('dashboard')">${ar?'العودة للوحة الطالب':'Back to dashboard'}</button></div><div id="student-tasks-grid" class="learning-dashboard-grid"><div class="card empty">${ar?'جارٍ تحميل المهام…':'Loading your tasks…'}</div></div></main>`);
  try{const d=await api('/api/student/learning'),host=document.getElementById('student-tasks-grid'),tasks=d.tasks||[];const pending=tasks.filter(t=>!['submitted','under_review','graded'].includes(t.submission_status)).length;host.innerHTML=`<div class="grid grid-3" style="margin-bottom:18px"><article class="card kpi"><div class="kpi-label">${ar?'إجمالي المهام':'Total tasks'}</div><div class="num">${tasks.length}</div></article><article class="card kpi"><div class="kpi-label">${ar?'مطلوب تسليمها':'To submit'}</div><div class="num">${pending}</div></article><article class="card kpi"><div class="kpi-label">${ar?'تم تسليمها / مراجعتها':'Submitted / reviewed'}</div><div class="num">${tasks.length-pending}</div></article></div><div class="learning-card-grid">${tasks.map(t=>{const source=t.course_title?['COURSE',t.course_title]:t.challenge_title?['CHALLENGE',t.challenge_title]:['CASE STUDY',t.case_title||'Training case'];const done=['submitted','under_review','graded'].includes(t.submission_status);return `<article class="card my-learning-card task-card-clickable" role="button" tabindex="0" onclick="openTaskDetail(${t.id})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openTaskDetail(${t.id})}"><div class="card-label-row"><span class="mini-tag">${source[0]}</span><span class="pill ${done?'pass':'active'}">${done?esc(t.submission_status): (ar?'مطلوبة':'Required')}</span></div><h3>${esc(t.title)}</h3><p>${esc(t.description||'')}</p><div class="learning-card-meta"><span>${esc(source[1])}</span><span>${Number(t.points)||0} ${ar?'نقطة':'points'}</span></div>${t.due_at?`<p class="small-text muted">${ar?'آخر موعد':'Due'}: ${esc(fmtDate(t.due_at))}</p>`:''}${t.resource_url?`<a class="btn ghost card-full-btn" onclick="event.stopPropagation()" href="${esc(t.resource_url)}" target="_blank" rel="noopener">${ar?'فتح رابط المهمة':'Open task resource'} ↗</a>`:''}${done?`<div class="small-text muted">${ar?'تم التسليم':'Submitted'}${t.submitted_at?' · '+esc(fmtDate(t.submitted_at)):''}${t.score!==null&&t.score!==undefined?' · '+(ar?'الدرجة':'Score')+': '+Number(t.score):''}</div><button class="btn ghost card-full-btn" onclick="event.stopPropagation();openTaskDetail(${t.id})">${ar?'عرض التفاصيل':'View details'}</button>`:`<button class="btn orange card-full-btn" onclick="event.stopPropagation();openTaskDetail(${t.id})">${ar?'عرض تفاصيل المهمة':'View task details'} →</button>`}</article>`}).join('')||`<div class="card empty"><h3>${ar?'لا توجد مهام مطلوبة حاليًا':'You’re all caught up'}</h3><p>${ar?'ستظهر هنا المهام المرتبطة بالكورسات والتحديات والحالات التدريبية المنشورة.':'Required tasks from enrolled courses, joined challenges, and published case studies will appear here.'}</p></div>`}</div>`;
  }catch(e){showError(e.message||'Could not load tasks','Tasks unavailable')}
}

async function renderStudentLearning(section='courses'){if(!state.me?.user){go('login');return}const ar=state.lang==='ar',isCourses=section==='courses';app.innerHTML=layout(`<main class="page"><div class="dashboard-head"><div><div class="eyebrow">STUDENT WORKSPACE</div><h1>${isCourses?(ar?'كورساتي':'My Courses'):(ar?'تحدياتي':'My Challenges')}</h1><p class="muted">${isCourses?(ar?'الكورسات المسجل فيها ونسبة تقدمك':'Your enrolled courses and learning progress'):(ar?'التحديات التي انضممت إليها وحالة تقدمك':'Challenges you have joined and your progress')}</p></div><button class="btn ghost" onclick="go('dashboard')">${ar?'العودة للوحة الطالب':'Back to dashboard'}</button></div><div id="my-learning-content" class="learning-dashboard-grid"><div class="card empty">${ar?'جارٍ تحميل بياناتك…':'Loading your learning activity…'}</div></div></main>`);try{const d=await api('/api/student/learning');const host=document.getElementById('my-learning-content');const card=(x,type)=>{const relatedTasks=(d.tasks||[]).filter(t=>type==='CHALLENGE'&&Number(t.challenge_id)===Number(x.id));return `<article class="card my-learning-card"><div class="eyebrow">${type}</div><h3>${esc(x.title)}</h3><p>${esc(x.short_description||'')}</p><div class="progress-track"><span style="width:${Number(x.progress)||0}%"></span></div><div class="learning-card-meta"><span>${esc(x.status||'active')}</span><span>${Number(x.progress)||0}% complete</span></div>${type==='CHALLENGE'?`<div class="learning-card-meta"><span>${ar?'المهام المطلوبة':'Required tasks'}</span><b>${relatedTasks.length}</b></div>${relatedTasks.slice(0,3).map(t=>`<div class="learning-task-row"><span>✓</span><b>${esc(t.title)}</b><button class="btn small orange" onclick='taskSubmissionForm(${t.id})'>${ar?'تسليم':'Submit'}</button></div>`).join('')}<button class="btn ghost card-full-btn" onclick="go('tasks')">${ar?'عرض كل المهام':'View all tasks'} ↗</button>`:''}${type==='COURSE'&&x.status!=='pending'&&x.status!=='rejected'?`<button class="btn orange card-full-btn" onclick="startCoursePlayer(${x.id})">${Number(x.progress)>0?'Continue learning':'Start learning'} ↗</button>`:''}</article>`};host.innerHTML=isCourses?`<section class="learning-dashboard-section"><div class="learning-card-grid">${d.courses.map(x=>card(x,'COURSE')).join('')||`<div class="card empty">${ar?'لم تسجل في أي كورس حتى الآن':'No courses enrolled yet.'}</div>`}</div></section>`:`<section class="learning-dashboard-section"><div class="learning-card-grid">${d.challenges.map(x=>card(x,'CHALLENGE')).join('')||`<div class="card empty">${ar?'لم تنضم إلى أي تحدٍ حتى الآن':'No challenges joined yet.'}</div>`}</div></section>`;/* keep the detailed task/case-study workspace available from the dashboard in a future dedicated view */ /* legacy workspace sections intentionally separated */ }catch(e){showError(e.message||'Could not load your learning','My Learning unavailable')}}
function adminCategoryOptions(cats,selected){return cats.map(c=>`<option value="${c.id}" ${Number(selected)===Number(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}
async function adminLearningCourses(el){try{const [rows,cats,exams]=await Promise.all([api('/api/admin/learning/courses'),api('/api/admin/learning/categories'),api('/api/admin/exams')]);window.__learningExams=exams;el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Learning management</div><h1>Courses</h1><p class="muted">Create and publish courses for the public catalog.</p></div><button class="btn orange" onclick="learningCourseForm()">+ New course</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Course</th><th>Category</th><th>Level / Duration</th><th>Enrollment</th><th>Status</th><th>Access</th><th>Actions</th></tr></thead><tbody>${rows.map(c=>`<tr><td><b>${esc(c.title)}</b><div class="small-text muted">${esc(c.short_description||'')}</div></td><td>${esc(c.category_name||'—')}</td><td>${esc(c.level)} · ${esc(c.duration||'Self-paced')}</td><td>${c.enrollment_count||0}</td><td><span class="pill">${esc(c.status)}</span></td><td>${esc(c.enrollment_mode)}</td><td><div class="actions"><button class="btn small ghost" onclick='learningCourseForm(${JSON.stringify(c).replace(/'/g,'&#39;')})'>Edit</button><button class="btn small orange" onclick="manageCourseContent(${c.id},'${esc(c.title).replaceAll("'","&#39;")}')">Content</button><button class="btn small danger" onclick="deleteLearningItem('courses',${c.id})">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No courses created yet. Use New course to add your first one.</td></tr>'}</tbody></table></div></div>`;window.__learningCats=cats}catch(e){showError(e.message||'Could not load courses','Course management unavailable')}}
function learningCourseForm(c={}){const cats=window.__learningCats||[];openModal(`<div class="modal-head"><div><div class="eyebrow">COURSE EDITOR</div><h2>${c.id?'Edit course':'Create course'}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveLearningItem(event,'courses',${c.id||0})"><div class="field"><label>Course title</label><input name="title" required maxlength="200" value="${esc(c.title||'')}"></div><div class="field"><label>URL slug (English letters/numbers)</label><input name="slug" required value="${esc(c.slug||'')}" placeholder="financial-modeling-basics"></div><div class="field"><label>Category</label><select name="categoryId"><option value="">Select category</option>${adminCategoryOptions(cats,c.category_id)}</select></div><div class="field"><label>Short description</label><textarea name="shortDescription" rows="2">${esc(c.short_description||'')}</textarea></div><div class="field"><label>Full description</label><textarea name="description" rows="4">${esc(c.description||'')}</textarea></div><div class="two-col"><div class="field"><label>Level</label><select name="level">${['Beginner','Intermediate','Advanced','All levels'].map(v=>`<option ${c.level===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Duration</label><input name="duration" value="${esc(c.duration||'')}" placeholder="6 hours / 4 weeks"></div><div class="field"><label>Publication status</label><select name="status">${['draft','published','archived'].map(v=>`<option ${c.status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Enrollment mode</label><select name="enrollmentMode">${[['open','Open'],['approval','Requires approval'],['invite','Invitation only']].map(([v,l])=>`<option value="${v}" ${c.enrollment_mode===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="card" style="padding:14px;background:var(--surface2)"><b>Final exam</b><p class="small-text muted" style="margin:6px 0 0">Create or link the final exam from Admin → Exams by selecting “Course Exam” and choosing this course. It will appear inside the course curriculum.</p></div><div class="field"><label>Completion requirements</label><textarea name="completionRequirements" rows="2">${esc(c.completion_requirements||'')}</textarea></div><button class="btn orange">Save course</button></form>`)}
async function adminLearningChallenges(el){try{const [rows,cats]=await Promise.all([api('/api/admin/learning/challenges'),api('/api/admin/learning/categories')]);window.__learningCats=cats;el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Program management</div><h1>Challenges</h1><p class="muted">Configure duration, pace, enrollment rules and publication.</p></div><button class="btn orange" onclick="learningChallengeForm()">+ New challenge</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Challenge</th><th>Duration</th><th>Pace</th><th>Enrollment</th><th>Students</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(c=>`<tr><td><b>${esc(c.title)}</b><div class="small-text muted">${esc(c.category_name||'')}</div></td><td>${c.duration_days} days</td><td>${esc(c.pace_mode)}</td><td>${esc(c.enrollment_mode)}</td><td>${c.enrollment_count||0}</td><td>${esc(c.status)}</td><td><div class="actions"><button class="btn small ghost" onclick='learningChallengeForm(${JSON.stringify(c).replace(/'/g,'&#39;')})'>Edit</button><button class="btn small orange" onclick="manageChallengeTasks(${c.id},'${esc(c.title).replaceAll("'","&#39;")}')">Tasks</button><button class="btn small danger" onclick="deleteLearningItem('challenges',${c.id})">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No challenges created yet.</td></tr>'}</tbody></table></div></div>`}catch(e){showError(e.message||'Could not load challenges','Challenge management unavailable')}}
function learningChallengeForm(c={}){const cats=window.__learningCats||[];openModal(`<div class="modal-head"><div><div class="eyebrow">CHALLENGE EDITOR</div><h2>${c.id?'Edit challenge':'Create challenge'}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveLearningItem(event,'challenges',${c.id||0})"><div class="field"><label>Challenge title</label><input name="title" required value="${esc(c.title||'')}"></div><div class="field"><label>URL slug</label><input name="slug" required value="${esc(c.slug||'')}" placeholder="30-day-excel-challenge"></div><div class="field"><label>Category</label><select name="categoryId"><option value="">Select category</option>${adminCategoryOptions(cats,c.category_id)}</select></div><div class="field"><label>Short description</label><textarea name="shortDescription" rows="2">${esc(c.short_description||'')}</textarea></div><div class="field"><label>Description</label><textarea name="description" rows="4">${esc(c.description||'')}</textarea></div><div class="two-col"><div class="field"><label>Duration (days)</label><input name="durationDays" type="number" min="1" max="365" value="${c.duration_days||30}" required></div><div class="field"><label>Level</label><select name="level">${['Beginner','Intermediate','Advanced','All levels'].map(v=>`<option ${c.level===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Challenge type</label><select name="paceMode"><option value="self_paced" ${c.pace_mode!=='cohort'?'selected':''}>Self-paced</option><option value="cohort" ${c.pace_mode==='cohort'?'selected':''}>Fixed cohort</option></select></div><div class="field"><label>Enrollment</label><select name="enrollmentMode">${[['open','Open'],['approval','Requires approval'],['invite','Invitation only']].map(([v,l])=>`<option value="${v}" ${c.enrollment_mode===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Start date (fixed cohort)</label><input name="startAt" type="datetime-local" value="${localInputValue(c.start_at)}"></div><div class="field"><label>End date</label><input name="endAt" type="datetime-local" value="${localInputValue(c.end_at)}"></div><div class="field"><label>Status</label><select name="status">${['draft','published','archived'].map(v=>`<option ${c.status===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label>Completion requirements</label><textarea name="completionRequirements" rows="2">${esc(c.completion_requirements||'')}</textarea></div><button class="btn orange">Save challenge</button></form>`)}
async function adminLearningCases(el){try{const [rows,cats]=await Promise.all([api('/api/admin/learning/cases'),api('/api/admin/learning/categories')]);window.__learningCats=cats;el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Practical learning</div><h1>Case Studies</h1><p class="muted">Publish scenarios, guiding questions and model solutions.</p></div><button class="btn orange" onclick="learningCaseForm()">+ New case study</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Case</th><th>Category</th><th>Difficulty</th><th>Mode</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(c=>`<tr><td><b>${esc(c.title)}</b><div class="small-text muted">${esc(c.short_description||'')}</div></td><td>${esc(c.category_name||'—')}</td><td>${esc(c.difficulty)}</td><td>${esc(c.access_mode)}</td><td>${esc(c.status)}</td><td><div class="actions"><button class="btn small ghost" onclick='learningCaseForm(${JSON.stringify({...c,data:JSON.parse(c.data_json||'[]')}).replace(/'/g,'&#39;')})'>Edit</button><button class="btn small danger" onclick="deleteLearningItem('cases',${c.id})">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No case studies created yet.</td></tr>'}</tbody></table></div></div>`}catch(e){showError(e.message||'Could not load case studies','Case study management unavailable')}}
function caseResourceRows(resources){let arr=Array.isArray(resources)?resources:[];if(!arr.length)arr=[{}];return arr.map(caseResourceRow).join('')}
function caseResourceRow(resource={}){return `<div class="attachment-row case-resource-row"><div class="field"><label>File name</label><input name="caseResourceName" maxlength="200" placeholder="e.g. Financial model template.xlsx" value="${esc(resource?.title||resource?.name||'')}"></div><div class="field"><label>File URL</label><input name="caseResourceUrl" type="url" maxlength="2000" placeholder="https://..." value="${esc(resource?.url||'')}"></div><button type="button" class="btn small ghost" onclick="this.closest('.case-resource-row').remove()">Remove</button></div>`}
function addCaseResourceRow(){document.getElementById('caseResourceRows')?.insertAdjacentHTML('beforeend',caseResourceRow())}
function learningCaseForm(c={}){const cats=window.__learningCats||[];openModal(`<div class="modal-head"><div><div class="eyebrow">CASE STUDY EDITOR</div><h2>${c.id?'Edit case study':'Create case study'}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveLearningItem(event,'cases',${c.id||0})"><div class="field"><label>Title</label><input name="title" required value="${esc(c.title||'')}"></div><div class="field"><label>URL slug</label><input name="slug" required value="${esc(c.slug||'')}"></div><div class="field"><label>Category</label><select name="categoryId"><option value="">Select category</option>${adminCategoryOptions(cats,c.category_id)}</select></div><div class="field"><label>Short description</label><textarea name="shortDescription" rows="2">${esc(c.short_description||'')}</textarea></div><div class="field"><label>Business scenario</label><textarea name="scenario" rows="5">${esc(c.scenario||'')}</textarea></div><div class="field"><label>Learning objectives</label><textarea name="objectives" rows="2">${esc(c.objectives||'')}</textarea></div><div class="field"><label>Guiding questions</label><textarea name="guidingQuestions" rows="4">${esc(c.guiding_questions||'')}</textarea></div><div class="field case-resource-manager"><div class="case-resource-heading"><div><label>Case files & resources</label><p class="muted small-text">Add a clear file name and its direct URL, just like assessment attachments.</p></div><button type="button" class="btn small ghost" onclick="addCaseResourceRow()">+ Add file</button></div><div id="caseResourceRows">${caseResourceRows(c.data||[])}</div></div><div class="field"><label>Guided solution</label><textarea name="solution" rows="5">${esc(c.solution||'')}</textarea></div><div class="field"><label>Evaluation criteria</label><textarea name="evaluationCriteria" rows="3">${esc(c.evaluation_criteria||'')}</textarea></div><div class="two-col"><div class="field"><label>Difficulty</label><select name="difficulty">${['Beginner','Intermediate','Advanced'].map(v=>`<option ${c.difficulty===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Access mode</label><select name="accessMode">${[['practice','Self-practice'],['graded','Graded submission'],['challenge','Challenge-based']].map(([v,l])=>`<option value="${v}" ${c.access_mode===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status">${['draft','published','archived'].map(v=>`<option ${c.status===v?'selected':''}>${v}</option>`).join('')}</select></div></div><button class="btn orange">Save case study</button></form>`)}
async function saveLearningItem(e,kind,id){e.preventDefault();const f=new FormData(e.target),data=Object.fromEntries(f);data.categoryId=data.categoryId?Number(data.categoryId):null;if(kind==='cases'){const names=[...e.target.querySelectorAll('[name="caseResourceName"]')];const urls=[...e.target.querySelectorAll('[name="caseResourceUrl"]')];data.data=names.map((n,i)=>({title:n.value.trim(),url:(urls[i]?.value||'').trim()})).filter(r=>r.title||r.url);for(const r of data.data){if(!r.title||!r.url){showError('Please enter both a file name and URL for each resource.','Incomplete case resource');return}try{const u=new URL(r.url);if(!['http:','https:'].includes(u.protocol))throw new Error();}catch{showError('Each file URL must be a valid http:// or https:// link.','Invalid file URL');return}}}if(kind==='challenges'){data.durationDays=Number(data.durationDays);data.startAt=data.startAt?new Date(data.startAt).toISOString():null;data.endAt=data.endAt?new Date(data.endAt).toISOString():null}if(kind==='courses'&&!data.slug)data.slug=data.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(kind==='challenges'&&!data.slug)data.slug=data.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(kind==='cases'&&!data.slug)data.slug=data.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');try{await api(`/api/admin/learning/${kind}${id?'/'+id:''}`,{method:id?'PUT':'POST',body:JSON.stringify(data)});closeModal();showToast('Saved successfully');adminTab(kind)}catch(x){showError(x.message||'Could not save content','Save failed')}}
async function deleteLearningItem(kind,id){if(!confirm('Delete this item? Related enrollments/content may also be removed.'))return;try{await api(`/api/admin/learning/${kind}/${id}`,{method:'DELETE'});showToast('Deleted');adminTab(kind)}catch(e){showError(e.message||'Could not delete item','Delete failed')}}
async function adminLearningEnrollments(el){try{const rows=await api('/api/admin/learning/enrollments');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Student management</div><h1>Enrollments</h1><p class="muted">Approve requests and mark course/challenge completion.</p></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Type</th><th>Content</th><th>Joined</th><th>Status</th><th>Progress</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.full_name)}</b><div class="small-text muted">${esc(r.email)}</div></td><td>${esc(r.content_type)}</td><td>${esc(r.content_title)}</td><td>${fmtDate(r.joined_at)}</td><td>${esc(r.status)}</td><td>${Number(r.progress)||0}%</td><td><div class="actions">${r.status==='pending'?`<button class="btn small orange" onclick="updateLearningEnrollment('${r.content_type}',${r.id},'active',${Number(r.progress)||0})">Approve</button><button class="btn small danger" onclick="updateLearningEnrollment('${r.content_type}',${r.id},'rejected',0)">Reject</button>`:''}<button class="btn small ghost" onclick="updateLearningEnrollment('${r.content_type}',${r.id},'completed',100)">Mark completed + issue certificate</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No enrollments yet.</td></tr>'}</tbody></table></div></div>`}catch(e){showError(e.message||'Could not load enrollments','Enrollment management unavailable')}}
async function updateLearningEnrollment(type,id,status,progress){const kind=type==='course'?'course':'challenge';try{await api(`/api/admin/learning/${kind}-enrollments/${id}`,{method:'PATCH',body:JSON.stringify({status,progress})});showToast(status==='completed'?'Marked complete; certificate issued or already exists.':'Enrollment updated');adminTab('enrollments')}catch(e){showError(e.message||'Could not update enrollment','Update failed')}}


async function manageCourseContent(courseId,title){
  try{
    const d=await api(`/api/admin/learning/courses/${courseId}/structure`);
    const safeTitle=String(title).replaceAll("'","&#39;");
    openModal(`<div class="modal-head"><div><div class="eyebrow">COURSE CONTENT</div><h2>${esc(title)}</h2><p class="muted">Edit modules, lessons and learning resources at any time, including after publishing.</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="content-manager"><h3>Modules & Lessons</h3>${d.modules.map(m=>`<div class="module-manager card"><div class="actions" style="justify-content:space-between;align-items:center"><b>📂 ${esc(m.title)}</b><div class="actions"><button class="btn small ghost" onclick="editLearningItem('modules',${m.id},${courseId},'${safeTitle}')">Edit module</button><button class="btn small danger" onclick="deleteLearningStructure('modules',${m.id},${courseId},'${safeTitle}')">Delete module</button></div></div>${m.description?`<div class="small-text muted">${esc(m.description)}</div>`:''}<div class="small-text muted" style="margin-top:10px">${d.lessons.filter(l=>Number(l.module_id)===Number(m.id)).map(l=>`<div class="resource-manager"><span>▶️ ${esc(l.title)} <small>(${esc(l.lesson_type||'text')})</small></span><div class="actions"><button class="btn small ghost" onclick="editLearningItem('lessons',${l.id},${courseId},'${safeTitle}')">Edit</button><button class="btn small danger" onclick="deleteLearningStructure('lessons',${l.id},${courseId},'${safeTitle}')">Delete</button></div></div>`).join('')||'No lessons yet'}${d.resources.filter(r=>Number(r.module_id)===Number(m.id)).map(r=>`<div class="resource-manager">📄 <a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)} ↗</a><div class="actions"><button class="btn small ghost" onclick="editLearningItem('resources',${r.id},${courseId},'${safeTitle}')">Edit</button><button class="btn small danger" onclick="deleteLearningStructure('resources',${r.id},${courseId},'${safeTitle}')">Delete</button></div></div>`).join('')}</div></div>`).join('')||'<p class="muted">No modules yet.</p>'}<form class="form compact-form" onsubmit="addLearningModule(event,${courseId},'${safeTitle}')"><h4>Add module</h4><div class="field"><label>Module title</label><input name="title" required></div><div class="field"><label>Description</label><input name="description"></div><button class="btn orange">Add module</button></form>${d.modules.length?`<form class="form compact-form" onsubmit="addLearningLesson(event,${courseId},'${safeTitle}')"><h4>Add lesson</h4><div class="field"><label>Module</label><select name="moduleId" required>${d.modules.map(m=>`<option value="${m.id}">${esc(m.title)}</option>`).join('')}</select></div><div class="field"><label>Lesson title</label><input name="title" required></div><div class="field"><label>Lesson content</label><textarea name="content" rows="3"></textarea></div><div class="two-col"><div class="field"><label>Type</label><select name="lessonType"><option value="text">Text</option><option value="video">Video</option><option value="file">File</option><option value="external">External resource</option></select></div><div class="field"><label>Resource URL</label><input name="resourceUrl" type="url"></div></div><button class="btn orange">Add lesson</button></form>`:''}<h3>Course-level resources</h3>${d.resources.filter(r=>!r.module_id).map(r=>`<div class="resource-manager">📄 <a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)} ↗</a><div class="actions"><button class="btn small ghost" onclick="editLearningItem('resources',${r.id},${courseId},'${safeTitle}')">Edit</button><button class="btn small danger" onclick="deleteLearningStructure('resources',${r.id},${courseId},'${safeTitle}')">Delete</button></div></div>`).join('')||'<p class="muted">No course-level resources.</p>'}<form class="form compact-form" onsubmit="addLearningResource(event,${courseId},'${safeTitle}')"><h4>Add resource</h4><div class="field"><label>Place in module (optional)</label><select name="moduleId"><option value="">Course-level sources</option>${d.modules.map(m=>`<option value="${m.id}">${esc(m.title)}</option>`).join('')}</select></div><div class="field"><label>Resource title</label><input name="title" required></div><div class="field"><label>URL</label><input name="url" type="url" required></div><button class="btn orange">Add resource</button></form></div>`)
  }catch(e){showError(e.message||'Could not load course content','Course content unavailable')}
}
async function editLearningItem(kind,id,courseId,title){
  try{
    const d=await api(`/api/admin/learning/courses/${courseId}/structure`);
    const item=(kind==='modules'?d.modules:kind==='lessons'?d.lessons:d.resources).find(x=>Number(x.id)===Number(id));
    if(!item)throw new Error('Item not found');
    const escTitle=String(title).replaceAll("'","&#39;");
    let form='';
    if(kind==='modules') form=`<form class="form" onsubmit="saveCourseStructureItem(event,'modules',${id},${courseId},'${escTitle}')"><div class="field"><label>Module title</label><input name="title" required maxlength="200" value="${esc(item.title)}"></div><div class="field"><label>Description</label><textarea name="description" rows="3">${esc(item.description||'')}</textarea></div><div class="field"><label>Order</label><input name="sortOrder" type="number" value="${Number(item.sort_order)||0}"></div><button class="btn orange">Save changes</button></form>`;
    else if(kind==='lessons') form=`<form class="form" onsubmit="saveCourseStructureItem(event,'lessons',${id},${courseId},'${escTitle}')"><div class="field"><label>Module</label><select name="moduleId" required>${d.modules.map(m=>`<option value="${m.id}" ${Number(m.id)===Number(item.module_id)?'selected':''}>${esc(m.title)}</option>`).join('')}</select></div><div class="field"><label>Lesson title</label><input name="title" required maxlength="200" value="${esc(item.title)}"></div><div class="field"><label>Lesson content</label><textarea name="content" rows="7">${esc(item.content||'')}</textarea></div><div class="two-col"><div class="field"><label>Type</label><select name="lessonType">${['text','video','file','external'].map(t=>`<option value="${t}" ${String(item.lesson_type)===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Resource URL</label><input name="resourceUrl" type="url" value="${esc(item.resource_url||'')}"></div></div><div class="field"><label>Order</label><input name="sortOrder" type="number" value="${Number(item.sort_order)||0}"></div><button class="btn orange">Save changes</button></form>`;
    else form=`<form class="form" onsubmit="saveCourseStructureItem(event,'resources',${id},${courseId},'${escTitle}')"><div class="field"><label>Resource title</label><input name="title" required maxlength="200" value="${esc(item.title)}"></div><div class="field"><label>URL</label><input name="url" type="url" required value="${esc(item.url)}"></div><div class="field"><label>Place in module</label><select name="moduleId"><option value="">Course-level sources</option>${d.modules.map(m=>`<option value="${m.id}" ${Number(m.id)===Number(item.module_id)?'selected':''}>${esc(m.title)}</option>`).join('')}</select></div><div class="field"><label>Type</label><select name="resourceType">${['link','file','video','document'].map(t=>`<option value="${t}" ${String(item.resource_type||'link')===t?'selected':''}>${t}</option>`).join('')}</select></div><button class="btn orange">Save changes</button></form>`;
    openModal(`<div class="modal-head"><div><div class="eyebrow">EDIT COURSE CONTENT</div><h2>${kind==='modules'?'Edit module':kind==='lessons'?'Edit lesson':'Edit resource'}</h2><p class="muted">Changes are saved without deleting or recreating the published course.</p></div><button class="icon-btn" onclick="manageCourseContent(${courseId},'${escTitle}')">×</button></div>${form}`);
  }catch(e){showError(e.message||'Could not open editor','Edit failed')}
}
async function saveCourseStructureItem(e,kind,id,courseId,title){
  e.preventDefault();const f=new FormData(e.target),data=Object.fromEntries(f.entries());
  if(kind==='resources'){data.courseId=courseId;data.moduleId=data.moduleId?Number(data.moduleId):null;data.resourceType=data.resourceType||(/\.pdf(\?|$)/i.test(data.url)?'file':'link')}
  if(kind==='lessons')data.moduleId=Number(data.moduleId);
  data.sortOrder=Number(data.sortOrder||0);
  try{await api(`/api/admin/learning/${kind}/${id}`,{method:'PUT',body:JSON.stringify(data)});showToast('Changes saved');await manageCourseContent(courseId,title)}catch(x){showError(x.message||'Could not save changes','Save failed')}
}
async function addLearningModule(e,courseId,title){e.preventDefault();const f=new FormData(e.target);try{await api('/api/admin/learning/modules',{method:'POST',body:JSON.stringify({courseId,title:f.get('title'),description:f.get('description')})});await manageCourseContent(courseId,title)}catch(x){showError(x.message||'Could not add module')}}
async function addLearningLesson(e,courseId,title){e.preventDefault();const f=new FormData(e.target);try{await api('/api/admin/learning/lessons',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});await manageCourseContent(courseId,title)}catch(x){showError(x.message||'Could not add lesson')}}
async function addLearningResource(e,courseId,title){e.preventDefault();const f=new FormData(e.target);try{await api('/api/admin/learning/resources',{method:'POST',body:JSON.stringify({courseId,moduleId:f.get('moduleId')?Number(f.get('moduleId')):null,title:f.get('title'),url:f.get('url'),resourceType:/\.pdf(\?|$)/i.test(f.get('url'))?'file':'link'})});await manageCourseContent(courseId,title)}catch(x){showError(x.message||'Could not add resource')}}
async function deleteLearningStructure(kind,id,courseId,title){if(!confirm('Delete this item?'))return;try{await api(`/api/admin/learning/${kind}/${id}`,{method:'DELETE'});await manageCourseContent(courseId,title)}catch(e){showError(e.message||'Could not delete item')}}
async function manageChallengeTasks(challengeId,title){state.taskChallengeId=challengeId;state.taskChallengeTitle=title;adminTab('tasks')}
async function adminLearningTasks(el){try{const [rows,courses,challenges,cases,submissions]=await Promise.all([api('/api/admin/learning/tasks'),api('/api/admin/learning/courses'),api('/api/admin/learning/challenges'),api('/api/admin/learning/cases'),api('/api/admin/learning/submissions')]);window.__taskLists={courses,challenges,cases};el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Learning operations</div><h1>Tasks & Submissions</h1><p class="muted">Create tasks for courses, challenges, and case studies. Review and grade student submissions here.</p></div><button class="btn orange" onclick="learningTaskForm(${state.taskChallengeId||0})">+ New task</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Task</th><th>Course</th><th>Challenge</th><th>Case study</th><th>Task link</th><th>Due date</th><th>Type</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr><td><b>${esc(t.title)}</b><div class="small-text muted">${esc(t.description||'')}</div></td><td>${esc(t.course_title||'—')}</td><td>${esc(t.challenge_title||'—')}</td><td>${esc(t.case_title||'—')}</td><td>${taskResourceList(t).length?taskResourceList(t).map(r=>`<a class="small-text" style="display:block;margin:3px 0" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a>`).join(''):'—'}</td><td>${t.due_at?fmtDate(t.due_at):'—'}</td><td>${esc(t.submission_type)}</td><td>${esc(t.status)}</td><td><div class="actions"><button class="btn small ghost" onclick='learningTaskForm(${state.taskChallengeId||0},${JSON.stringify(t).replace(/'/g,'&#39;')})'>Edit</button><button class="btn small danger" onclick="deleteLearningTask(${t.id})">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="9" class="empty">No tasks yet. Create a task and attach it to a course, challenge, or case study.</td></tr>'}</tbody></table></div></div><div class="dashboard-head" style="margin-top:26px"><div><div class="eyebrow">Student work</div><h2>Submissions for review</h2></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Task</th><th>Student</th><th>Submitted</th><th>Submission</th><th>Status / Score</th><th>Action</th></tr></thead><tbody>${submissions.map(sub=>`<tr><td><b>${esc(sub.task_title)}</b></td><td>${esc(sub.full_name)}<div class="small-text muted">${esc(sub.email)}</div></td><td>${fmtDate(sub.submitted_at)}</td><td>${sub.file_url?`<a href="${esc(sub.file_url)}" target="_blank" rel="noopener">Open file ↗</a>`:''}${sub.submission_text?`<div class="small-text">${esc(sub.submission_text.slice(0,180))}</div>`:''}</td><td>${esc(sub.status)}${sub.score!==null?` · ${Number(sub.score)} pts`:''}</td><td><button class="btn small orange" onclick='gradeLearningSubmission(${JSON.stringify(sub).replace(/'/g,'&#39;')})'>Grade</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No submissions received yet.</td></tr>'}</tbody></table></div></div>`}catch(e){showError(e.message||'Could not load tasks','Task management unavailable')}}
function taskResourceList(task){let items=[];try{items=Array.isArray(task?.resource_links_json)?task.resource_links_json:JSON.parse(task?.resource_links_json||'[]')}catch{}if(!Array.isArray(items))items=[];if(!items.length&&task?.resource_url)items=[{title:'Task resource',url:task.resource_url}];return items.filter(x=>x&&(x.title||x.name||x.url)).map(x=>({title:String(x.title||x.name||''),url:String(x.url||'')}))}
function taskResourceRow(resource={}){return `<div class="attachment-row case-resource-row task-resource-row"><div class="field"><label>File / resource name</label><input name="taskResourceName" maxlength="200" placeholder="e.g. Financial model template.xlsx" value="${esc(resource?.title||'')}"></div><div class="field"><label>Link URL</label><input name="taskResourceUrl" type="url" maxlength="2000" placeholder="https://..." value="${esc(resource?.url||'')}"></div><button type="button" class="btn small ghost" onclick="this.closest('.task-resource-row').remove()">Remove</button></div>`}
function addTaskResourceRow(resource={}){document.getElementById('taskResourceRows')?.insertAdjacentHTML('beforeend',taskResourceRow(resource))}
function learningTaskForm(challengeId=0,task=null){const d=window.__taskLists||{courses:[],challenges:[],cases:[]};const editing=!!task;const val=(k)=>esc(task?.[k]??'');const taskResources=taskResourceList(task);const selected=(key,id)=>String(task?.[key]??'')===String(id)?'selected':'';let due='';if(task?.due_at){const dt=new Date(task.due_at);if(!Number.isNaN(dt.getTime()))due=new Date(dt.getTime()-dt.getTimezoneOffset()*60000).toISOString().slice(0,16)}openModal(`<div class="modal-head"><div><div class="eyebrow">TASK EDITOR</div><h2>${editing?'Edit task':'Create task'}</h2></div><button class="icon-btn" onclick="closeModal()" aria-label="Close">×</button></div><form class="form" onsubmit="saveLearningTask(event,${editing?Number(task.id):'null'})"><div class="field"><label>Task title</label><input name="title" required maxlength="200" value="${val('title')}"></div><div class="field"><label>Instructions</label><textarea name="description" rows="5">${val('description')}</textarea></div><div class="field case-resource-manager"><div class="case-resource-heading"><div><label>Task files & resources</label><p class="muted small-text">Add multiple named links, like the resources section in Case Studies. Existing single links are kept.</p></div><button type="button" class="btn small ghost" onclick="addTaskResourceRow()">+ Add link</button></div><div id="taskResourceRows">${(taskResources.length?taskResources:[{}]).map(taskResourceRow).join('')}</div></div><div class="two-col"><div class="field"><label>Related course (optional)</label><select name="courseId"><option value="">None</option>${d.courses.map(c=>`<option value="${c.id}" ${selected('course_id',c.id)}>${esc(c.title)}</option>`).join('')}</select></div><div class="field"><label>Related challenge (optional)</label><select name="challengeId"><option value="">None</option>${d.challenges.map(c=>`<option value="${c.id}" ${Number(task?.challenge_id||challengeId)===Number(c.id)?'selected':''}>${esc(c.title)}</option>`).join('')}</select></div><div class="field"><label>Case study (optional)</label><select name="caseStudyId"><option value="">None</option>${d.cases.map(c=>`<option value="${c.id}" ${selected('case_study_id',c.id)}>${esc(c.title)}</option>`).join('')}</select></div><div class="field"><label>Submission type</label><select name="submissionType"><option value="text" ${selected('submission_type','text')}>Text response</option><option value="file" ${selected('submission_type','file')}>File / workbook</option><option value="url" ${selected('submission_type','url')}>External URL</option><option value="exam" ${selected('submission_type','exam')}>Exam</option></select></div><div class="field"><label>Due date</label><input name="dueAt" type="datetime-local" value="${due}"></div><div class="field"><label>Points</label><input name="points" type="number" min="0" value="${Number(task?.points||0)}"></div><div class="field"><label>Status</label><select name="status"><option value="published" ${selected('status','published')}>Published</option><option value="draft" ${selected('status','draft')}>Draft</option></select></div></div><label class="check-row"><input type="checkbox" name="required" ${task?Number(task.required)!==0?'checked':'':'checked'}> Required for completion</label><button class="btn orange">${editing?'Save changes':'Create task'}</button></form>`)}
async function saveLearningTask(e,id=null){e.preventDefault();const f=new FormData(e.target),data=Object.fromEntries(f);data.resourceLinks=[...e.target.querySelectorAll('[name="taskResourceName"]')].map((n,i)=>({title:n.value.trim(),url:(e.target.querySelectorAll('[name="taskResourceUrl"]')[i]?.value||'').trim()})).filter(r=>r.title||r.url);for(const r of data.resourceLinks){if(!r.title||!r.url){showError('Please enter both a resource name and URL for each link.','Incomplete task resource');return}try{const u=new URL(r.url);if(!['http:','https:'].includes(u.protocol))throw new Error()}catch{showError('Each resource URL must be a valid http:// or https:// link.','Invalid resource URL');return}}for(const k of ['courseId','challengeId','caseStudyId'])data[k]=data[k]?Number(data[k]):null;data.points=Number(data.points||0);data.required=f.has('required');data.dueAt=data.dueAt?new Date(data.dueAt).toISOString():null;try{await api(id?`/api/admin/learning/tasks/${id}`:'/api/admin/learning/tasks',{method:id?'PUT':'POST',body:JSON.stringify(data)});closeModal();showToast(id?'Task updated':'Task created');adminTab('tasks')}catch(x){showError(x.message||'Could not save task',id?'Task update failed':'Task creation failed')}}
async function deleteLearningTask(id){if(!confirm('Delete this task?'))return;try{await api(`/api/admin/learning/tasks/${id}`,{method:'DELETE'});adminTab('tasks')}catch(e){showError(e.message||'Could not delete task')}}

async function loadCaseSolution(id,details){const host=details.querySelector('.case-solution-body');if(details.dataset.loaded==='1')return;host.innerHTML='<p class="muted">Loading guided solution…</p>';try{const d=await api(`/api/learning/cases/${id}/solution`);host.innerHTML=`<h3>Guided Solution</h3><p>${esc(d.solution||'A guided solution has not been published yet.').replaceAll('\n','<br>')}</p><h3>Evaluation Criteria</h3><p>${esc(d.evaluationCriteria||'')}</p>`;details.dataset.loaded='1'}catch(e){host.innerHTML=`<p class="danger-text">${esc(e.message||'Could not load solution')}</p>`}}

async function openTaskDetail(id){
  const ar=state.lang==='ar';
  try{
    const d=await api('/api/student/learning');
    const t=(d.tasks||[]).find(x=>Number(x.id)===Number(id));
    if(!t){showError(ar?'لم نتمكن من العثور على تفاصيل هذه المهمة.':'Task details could not be found.');return;}
    const source=t.course_title?{label:ar?'كورس':'COURSE',title:t.course_title}:t.challenge_title?{label:ar?'تحدٍ':'CHALLENGE',title:t.challenge_title}:{label:ar?'حالة تدريبية':'CASE STUDY',title:t.case_title||'Training case'};
    const done=['submitted','under_review','graded'].includes(t.submission_status);
    const statusLabel=done?(t.submission_status==='graded'?(ar?'تم التقييم':'Graded'):t.submission_status==='under_review'?(ar?'قيد المراجعة':'Under review'):(ar?'تم التسليم':'Submitted')):(ar?'مطلوبة':'Required');
    openModal(`<div class="task-detail-modal"><div class="task-detail-hero"><div class="task-detail-top"><span class="task-detail-brand-mark">AF</span><span class="task-detail-eyebrow">${ar?'تفاصيل المهمة':'TASK BRIEF'}</span><span class="task-detail-spacer"></span><button class="icon-btn" onclick="closeModal()" aria-label="Close">×</button></div><div class="task-detail-labels"><span class="mini-tag">${esc(source.label)}</span><span class="pill ${done?'pass':'active'}">${esc(statusLabel)}</span></div><h2>${esc(t.title)}</h2><p>${esc(t.description||(ar?'لا توجد تعليمات إضافية لهذه المهمة.':'No additional instructions have been provided for this task.')).replaceAll('\n','<br>')}</p></div><div class="task-detail-body"><section class="task-detail-panel"><div class="task-detail-panel-head"><span>${ar?'معلومات المهمة':'TASK OVERVIEW'}</span><b>01</b></div><div class="task-detail-meta-grid"><div><small>${ar?'مرتبطة بـ':'RELATED TO'}</small><b>${esc(source.title)}</b></div><div><small>${ar?'الدرجة':'POINTS'}</small><b>${Number(t.points)||0} ${ar?'نقطة':'pts'}</b></div><div><small>${ar?'آخر موعد للتسليم':'DUE DATE'}</small><b>${t.due_at?esc(fmtDate(t.due_at)):(ar?'غير محدد':'No deadline')}</b></div><div><small>${ar?'نوع التسليم':'SUBMISSION TYPE'}</small><b>${esc(t.submission_type||'text').replaceAll('_',' ')}</b></div></div></section>${taskResourceList(t).length?`<section class="task-detail-panel"><div class="task-detail-panel-head"><span>${ar?'ملفات وروابط المهمة':'TASK FILES & RESOURCES'}</span><b>${String(taskResourceList(t).length).padStart(2,'0')}</b></div><div class="task-detail-resource-list">${taskResourceList(t).map((r,i)=>`<a class="task-detail-resource" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer"><span class="task-detail-resource-icon">↗</span><span><b>${esc(r.title||((ar?'رابط المهمة ':'Task resource ')+(i+1)))}</b><small>${esc(r.url)}</small></span><strong>${ar?'فتح ↗':'Open ↗'}</strong></a>`).join('')}</div></section>`:''}${done?`<section class="task-detail-panel"><div class="task-detail-panel-head"><span>${ar?'حالة التسليم':'SUBMISSION STATUS'}</span><b>03</b></div><div class="task-detail-submission-state"><span class="task-detail-state-icon">✓</span><div><b>${esc(statusLabel)}</b><p>${t.submitted_at?(ar?'تاريخ التسليم: ':'Submitted: ')+esc(fmtDate(t.submitted_at)):(ar?'تم تسجيل تسليمك لهذه المهمة.':'Your submission has been recorded.')}${t.score!==null&&t.score!==undefined?' · '+(ar?'الدرجة: ':'Score: ')+Number(t.score):''}</p>${t.feedback?`<p>${ar?'ملاحظات المقيّم: ':'Reviewer feedback: '}${esc(t.feedback)}</p>`:''}</div></div></section>`:''}<div class="task-detail-actions"><button class="btn ghost" onclick="closeModal()">${ar?'إغلاق':'Close'}</button><button class="btn orange" onclick="taskSubmissionForm(${Number(t.id)})">${done?(ar?'تعديل التسليم':'Update submission'):(ar?'ابدأ تسليم المهمة':'Start task submission')} →</button></div></div></div>`);
  }catch(e){showError(e.message||'Could not load task details','Task unavailable')}
}
async function taskSubmissionForm(id){let title='Task submission';try{const d=await api('/api/student/learning');title=(d.tasks||[]).find(x=>Number(x.id)===Number(id))?.title||title}catch{}openModal(`<div class="modal-head"><div><div class="eyebrow">TASK SUBMISSION</div><h2>${esc(title)}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveTaskSubmission(event,${id})"><div class="field"><label>Your answer / notes</label><textarea name="submissionText" rows="5" placeholder="Describe your approach and findings..."></textarea></div><div class="field"><label>File or workbook URL</label><input name="fileUrl" type="url" placeholder="https://..."></div><button class="btn orange">Submit task</button></form>`)}
async function saveTaskSubmission(e,id){e.preventDefault();const f=new FormData(e.target);try{await api(`/api/learning/tasks/${id}/submit`,{method:'POST',body:JSON.stringify({submissionText:f.get('submissionText'),fileUrl:f.get('fileUrl')})});closeModal();showToast('Task submitted successfully');renderStudentLearning()}catch(x){showError(x.message||'Could not submit task','Submission failed')}}
function gradeLearningSubmission(sub){openModal(`<div class="modal-head"><div><div class="eyebrow">GRADE SUBMISSION</div><h2>${esc(sub.task_title)}</h2><p class="muted">${esc(sub.full_name)} · ${fmtDate(sub.submitted_at)}</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveLearningGrade(event,${sub.id})"><div class="field"><label>Status</label><select name="status">${['under_review','graded','returned'].map(v=>`<option value="${v}" ${sub.status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Score</label><input name="score" type="number" min="0" step="0.1" value="${sub.score??''}"></div><div class="field"><label>Feedback</label><textarea name="feedback" rows="4">${esc(sub.feedback||'')}</textarea></div><button class="btn orange">Save evaluation</button></form>`)}
async function saveLearningGrade(e,id){e.preventDefault();const f=new FormData(e.target);try{await api(`/api/admin/learning/submissions/${id}`,{method:'PATCH',body:JSON.stringify({status:f.get('status'),score:f.get('score'),feedback:f.get('feedback')})});closeModal();showToast('Evaluation saved');adminTab('tasks')}catch(x){showError(x.message||'Could not grade submission','Evaluation failed')}}

async function openCourseLesson(id){try{const d=await api(`/api/learning/lessons/${id}`);const courseId=Number(d.lesson.course_id);await startCoursePlayer(courseId,id)}catch(e){if(e.message==='Sign in to access lesson content.')go('login');else showError(e.message||'Could not open lesson','Lesson unavailable')}}
async function completeCourseLesson(id){try{const d=await api(`/api/learning/lessons/${id}/complete`,{method:'POST',body:JSON.stringify({})});showToast(`Lesson completed · Course progress ${d.progress}%`);closeModal();renderStudentLearning()}catch(e){showError(e.message||'Could not update lesson progress','Progress update failed')}}

async function adminCaseSubmissions(el){try{const rows=await api('/api/admin/learning/case-submissions');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Practical evaluation</div><h1>Case Study Submissions</h1><p class="muted">Review student analysis and provide scores and feedback.</p></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Case</th><th>Student</th><th>Submitted</th><th>Response</th><th>Status / Score</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.case_title)}</b></td><td>${esc(r.full_name)}<div class="small-text muted">${esc(r.email)}</div></td><td>${fmtDate(r.submitted_at)}</td><td>${r.file_url?`<a href="${esc(r.file_url)}" target="_blank" rel="noopener">Open file ↗</a>`:''}${r.response?`<div class="small-text">${esc(r.response.slice(0,180))}</div>`:''}</td><td>${esc(r.status)}${r.score!==null?` · ${Number(r.score)} pts`:''}</td><td><button class="btn small orange" onclick='gradeCaseSubmission(${JSON.stringify(r).replace(/'/g,'&#39;')})'>Evaluate</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No case study submissions yet.</td></tr>'}</tbody></table></div></div>`}catch(e){showError(e.message||'Could not load case submissions','Submissions unavailable')}}
function gradeCaseSubmission(r){openModal(`<div class="modal-head"><div><div class="eyebrow">CASE STUDY EVALUATION</div><h2>${esc(r.case_title)}</h2><p class="muted">${esc(r.full_name)} · ${fmtDate(r.submitted_at)}</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveCaseGrade(event,${r.id})"><div class="field"><label>Status</label><select name="status">${['under_review','graded'].map(v=>`<option value="${v}" ${r.status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Score</label><input name="score" type="number" min="0" step="0.1" value="${r.score??''}"></div><div class="field"><label>Feedback</label><textarea name="feedback" rows="4">${esc(r.feedback||'')}</textarea></div><button class="btn orange">Save evaluation</button></form>`)}
async function saveCaseGrade(e,id){e.preventDefault();const f=new FormData(e.target);try{await api(`/api/admin/learning/case-submissions/${id}`,{method:'PATCH',body:JSON.stringify({status:f.get('status'),score:f.get('score'),feedback:f.get('feedback')})});closeModal();showToast('Case evaluation saved');adminTab('case-submissions')}catch(x){showError(x.message||'Could not save evaluation','Evaluation failed')}}

async function toggleLearningCertificate(id,status){if(!confirm(`${status==='revoked'?'Revoke':'Restore'} this learning certificate?`))return;try{await api(`/api/admin/learning/certificates/${id}`,{method:'PATCH',body:JSON.stringify({status})});showToast('Learning certificate updated');adminTab('certificates')}catch(e){showError(e.message||'Could not update learning certificate')}}
